async function initApp() {
    try {
        await loadData();
        startSessionGuard();
        applyAllWidgetLayouts(); // จัดวิดเจ็ตตามค่าเริ่มต้นใน WIDGET_BOARDS
        hideLoginView();
        showMainLayout();
        
        // Set user UI info
        document.getElementById("user-display-name").innerText = currentUser ? currentUser.name : "User";
        document.getElementById("user-role-display").innerText = currentUser ? getRoleLabel(currentUser.role) : "";
        const me = currentUser && users.find(u => u.id === currentUser.id);
        if (me && me.avatarUrl !== undefined) currentUser.avatarUrl = me.avatarUrl; // ล็อกอินค้างไว้ → เอารูปล่าสุดจาก profiles
        renderMyAvatar();

        // Initial View
        // บัญชีนายจ้าง (Client) เข้าหน้าพอร์ทัลของตัวเองเลย ไม่ใช่แดชบอร์ดภายใน
        // กดรีเฟรชเบราว์เซอร์ → กลับมาหน้าเดิม (และแท็บย่อยหน้าการเงิน) ที่ทำงานอยู่ในแท็บนี้
        // (ตั้งสิทธิ์ก่อน เพื่อเช็คได้ว่าบัญชีนี้ยังเข้าหน้านั้นได้ — เมนูที่ไม่มีสิทธิ์ถูกซ่อนไว้)
        setupFormPermissions();
        const lastView = readSessionValue('mw_last_view');
        const lastMenu = lastView ? document.getElementById(`menu-${lastView}`) : null;
        const canRestore = currentUser && currentUser.role !== 'client' && lastMenu && document.getElementById(`view-${lastView}`)
            && !lastMenu.classList.contains('hidden') && getComputedStyle(lastMenu).display !== 'none';
        switchView(currentUser && currentUser.role === 'client' ? 'client-portal' : (canRestore ? lastView : 'dashboard'));
        setupAllSearchSuggestions();
        setupAllSearchSelects();
        // ตัวกรองตารางแจ้งงานที่เลือกได้หลายค่า
        setupMultiFilter("filter-job-type", "ทุกประเภทงาน", "ประเภทงาน");
        setupMultiFilter("filter-job-status", "ทุกสถานะงาน", "สถานะ");
        setupMultiFilter("filter-job-assignee", "ผู้รับผิดชอบ: ทุกคน", "ผู้รับผิดชอบ");
    } catch (e) {
        console.error("Error initializing app: ", e);
        logout(); // force logout to clear corrupted state
    }
}

// ==================== SEARCH SUGGESTIONS / AUTO-SUGGEST (ใช้ร่วมกันทุกช่องค้นหาในระบบ) ====================
// ผูก dropdown แนะนำคำค้นหาให้ input ค้นหา 1 ช่อง — ไม่แก้ตรรกะกรองตารางเดิมเลย แค่ช่วยเลือกคำค้นหาได้เร็วขึ้น
// getItems: () => คืน array รายการที่จะแนะนำ (เรียกใหม่ทุกครั้งที่พิมพ์ เพื่อให้เห็นข้อมูลล่าสุดเสมอ)
// getLabel/getSub: item -> ข้อความหลัก/รองที่โชว์ในรายการแนะนำ — ค่าที่คลิกแล้วเติมลงช่องค้นหาคือ getLabel เสมอ
// renderFn: ฟังก์ชัน render ตารางเดิมของหน้านั้น (เรียกซ้ำหลังเลือกคำแนะนำ เพื่อกรองตารางทันที)
const _searchSuggestRegistered = new Set();

// ปุ่มลูกศรขึ้น/ลง เลื่อนเลือกรายการใน dropdown + Enter เลือก, Esc ปิด — ใช้ร่วมกันทั้ง registerSearchSuggest/registerSearchSelect
// รายการที่เลือกได้ต้องมี data-idx (บรรทัด "ไม่พบข้อมูล" ไม่มี จึงข้ามไปเอง)
function attachSuggestKeyboard(input, dropdown, pick, hide, reopen) {
    input.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') { hide(); return; }
        if ((e.key === 'ArrowDown' || e.key === 'ArrowUp') && dropdown.classList.contains('hidden') && reopen) reopen();
        const items = Array.from(dropdown.querySelectorAll('.search-suggest-item[data-idx]'));
        if (dropdown.classList.contains('hidden') || items.length === 0) return;
        let cur = items.findIndex(el => el.classList.contains('active'));
        if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
            e.preventDefault();
            cur = e.key === 'ArrowDown' ? (cur + 1) % items.length : (cur <= 0 ? items.length - 1 : cur - 1);
            items.forEach((el, i) => el.classList.toggle('active', i === cur));
            items[cur].scrollIntoView({ block: 'nearest' });
        } else if (e.key === 'Enter' && cur >= 0) {
            e.preventDefault();
            pick(Number(items[cur].dataset.idx));
        }
    });
}

function registerSearchSuggest(inputId, getItems, getLabel, getSub, renderFn) {
    if (_searchSuggestRegistered.has(inputId)) return; // กัน event listener ซ้อนถ้า initApp() ถูกเรียกมากกว่า 1 ครั้ง (logout แล้ว login ใหม่)
    const input = document.getElementById(inputId);
    if (!input) return;
    const box = input.closest('.search-box');
    if (!box) return;
    _searchSuggestRegistered.add(inputId);

    let dropdown = document.getElementById(`${inputId}-suggest`);
    if (!dropdown) {
        dropdown = document.createElement('div');
        dropdown.className = 'search-suggest-dropdown hidden';
        dropdown.id = `${inputId}-suggest`;
        box.appendChild(dropdown);
    }

    function hide() {
        dropdown.classList.add('hidden');
        dropdown.innerHTML = '';
    }

    function showSuggestions() {
        const query = input.value.trim().toLowerCase();
        if (!query) { hide(); return; }

        const items = getItems() || [];
        const matches = items.filter(item => {
            const label = (getLabel(item) || '').toLowerCase();
            const sub = (getSub(item) || '').toLowerCase();
            return label.includes(query) || sub.includes(query);
        }).slice(0, 8);

        if (matches.length === 0) { hide(); return; }

        dropdown.innerHTML = matches.map((item, idx) => {
            const label = getLabel(item) || '';
            const sub = getSub(item) || '';
            return `
                <div class="search-suggest-item" data-idx="${idx}">
                    <span class="search-suggest-label">${label}</span>
                    ${sub ? `<span class="search-suggest-sub">${sub}</span>` : ''}
                </div>
            `;
        }).join('');
        dropdown.classList.remove('hidden');

        currentMatches = matches;
        Array.from(dropdown.children).forEach((el, idx) => {
            el.addEventListener('mousedown', (e) => {
                e.preventDefault(); // กันไม่ให้ input blur ก่อนที่ click จะทำงาน
                pick(idx);
            });
        });
    }

    let currentMatches = [];
    function pick(idx) {
        input.value = getLabel(currentMatches[idx]) || '';
        hide();
        renderFn();
        input.focus();
    }

    input.addEventListener('input', showSuggestions);
    input.addEventListener('focus', showSuggestions);
    input.addEventListener('blur', () => setTimeout(hide, 150));
    attachSuggestKeyboard(input, dropdown, pick, hide, showSuggestions);
}

// รวบรวมใบงาน (ใช้ทั้งหน้า "ระบบแจ้งงาน" และแท็บ "ออกบิล/รับเงิน") เป็นรายการแนะนำที่มี label/sub
// ตรงกับสิ่งที่ renderJobs()/renderBillingTab() ใช้กรองจริง (ชื่อคนงาน หรือชื่อนายจ้างถ้าไม่พบคนงาน)
function buildJobSuggestItems() {
    // แนะนำทั้งชื่อคนงานและชื่อนายจ้าง (ไม่ซ้ำ) — ช่องว่างซ้อนในชื่อยุบเหลือช่องเดียว (ชื่อพม่าจาก OCR มักมีช่องว่างเกิน)
    const tidy = s => String(s || '').replace(/\s+/g, ' ').trim();
    const seen = new Set();
    const out = [];
    jobs.forEach(j => {
        const work = workers.find(w => w.id === j.workerId);
        const cust = customers.find(c => c.id === j.customerId);
        const custName = tidy(cust && cust.companyName);
        if (work) {
            const label = tidy(`${work.firstName || ''} ${work.lastName || ''}`);
            if (label && !seen.has('w:' + label)) { seen.add('w:' + label); out.push({ label, sub: [work.workerUid, custName].filter(Boolean).join(' • ') }); }
        }
        if (custName && !seen.has('c:' + custName)) { seen.add('c:' + custName); out.push({ label: custName, sub: 'นายจ้าง' }); }
    });
    return out;
}

// ตั้งค่า auto-suggest ให้ครบทุกช่องค้นหาในระบบ — เรียกครั้งเดียวตอน initApp()
function setupAllSearchSuggestions() {
    registerSearchSuggest('search-customer', () => customers,
        c => c.companyName, c => c.taxId, renderCustomers);

    // ช่องค้นหาคนงานแนะนำทั้งชื่อคนงานและชื่อนายจ้าง (แทน dropdown กรองนายจ้างเดิม) — renderWorkers() ค้นชื่อนายจ้างอยู่แล้ว
    registerSearchSuggest('search-worker', () => workers.map(w => ({ label: `${w.firstName || ''} ${w.lastName || ''}`.trim(), sub: w.workerUid || w.passportNo }))
            .concat(customers.filter(c => !isCustomerInactive(c)).map(c => ({ label: c.companyName, sub: `นายจ้าง${c.taxId ? ' · ' + c.taxId : ''}` }))),
        x => x.label, x => x.sub, renderWorkers);

    registerSearchSuggest('search-job', buildJobSuggestItems,
        x => x.label, x => x.sub, renderJobs);

    registerSearchSuggest('search-agent', () => agents, a => a.name, () => '', renderAgentsList);

    registerSearchSuggest('search-billing', buildJobSuggestItems,
        x => x.label, x => x.sub, renderBillingTab);

    registerSearchSuggest('search-expense', () => expenses, e => e.description, e => e.category, renderExpenses);

    registerSearchSuggest('search-bank', () => banks, b => b.bankName, b => b.accountName, renderBanks);

    registerSearchSuggest('search-user', () => users, u => u.name, u => u.email, renderUsers);

    // เหมือนช่องค้นหาหน้าคนงาน: แนะนำทั้งชื่อคนงานและชื่อนายจ้าง
    registerSearchSuggest('search-renewal', () => workers.map(w => ({ label: `${w.firstName || ''} ${w.lastName || ''}`.trim(), sub: w.workerUid || w.passportNo }))
            .concat(customers.filter(c => !isCustomerInactive(c)).map(c => ({ label: c.companyName, sub: `นายจ้าง${c.taxId ? ' · ' + c.taxId : ''}` }))),
        x => x.label, x => x.sub, renderRenewalGroups);

    registerSearchSuggest('search-dashboard-employer-alerts', () => customers,
        c => c.companyName, c => c.taxId, renderEmployerAlerts);

    registerSearchSuggest('search-dashboard-missing-docs', () => workers.filter(isWorkerMissingDocs),
        w => `${w.firstName || ''} ${w.lastName || ''}`.trim(),
        w => { const emp = customers.find(c => c.id === w.employerId); return [w.workerUid, emp ? emp.companyName : ''].filter(Boolean).join(' · '); },
        renderMissingDocsOverview);
}

// ==================== SEARCH-SELECT (ค้นหาเพื่อ "เลือกข้อมูล 1 รายการ" จากระบบ — นายจ้าง, ลูกจ้าง, Agent ฯลฯ) ====================
// กฎมาตรฐานของโปรเจกต์: ช่องไหนก็ตามที่ให้ผู้ใช้ "ค้นหาเพื่อเลือกข้อมูล 1 รายการที่มีอยู่จริงในระบบ" จากชุดข้อมูลที่อาจยาวขึ้น
// เรื่อยๆ (นายจ้าง/ลูกค้า, ลูกจ้าง/คนงาน, Agent ฯลฯ) ต้องใช้ registerSearchSelect() นี้เสมอ แทนการให้พิมพ์ข้อความเองอิสระ
// หรือ <select> ยาวๆ ที่ต้องเลื่อนหา — เป็น dropdown แนะนำขณะพิมพ์มาตรฐานเดียวกับ registerSearchSuggest() ด้านบน
// (ใช้ CSS class เดียวกัน: .search-box / .search-suggest-dropdown) ต่างกันตรงที่ตัวนี้คืนค่าเป็น "รายการที่เลือกจริง"
// (มี id) ให้ onSelect แทนแค่เติมข้อความแล้วกรองตารางเดิม — ดูรายละเอียดกฎเต็มใน CLAUDE.md หัวข้อ "Search-to-select fields"
//
// ไม่ใช้ pattern นี้กับ: (1) ตัวเลือกตายตัวจำนวนน้อย เช่น สถานะ/สัญชาติ/เพศ — ใช้ <select> ปกติต่อไป หรือ
// (2) การเลือกได้หลายรายการพร้อมกันที่ต้องเห็นรายการที่เลือกไว้ค้างอยู่ตลอด — ใช้ checklist แบบ job-worker-picker แทน
//
// ถ้าช่องนั้นมี <select> เดิมอยู่แล้วที่โค้ดจุดอื่นยังอ่าน/เขียน .value อยู่ (เช่น validation, ผูก onchange เดิม) ให้
// ซ่อน <select> นั้นไว้ (class="hidden") เป็น "แหล่งเก็บค่าจริง" ต่อไป แล้วผูก getValue/setValue เข้ากับมัน — ไม่ต้องแก้
// โค้ดเดิมที่อ่าน/เขียนค่านั้นเลย (รูปแบบเดียวกับ <select id="job-worker-id"> ที่ซ่อนไว้หลัง job-worker-picker)
const searchSelectConfigs = {};
const _searchSelectRegistered = new Set();

// config: { inputId, getValue, setValue, getPool, getId, getLabel, getSub, getBadge, emptyText, onSelect, onClear }
function registerSearchSelect(key, config) {
    searchSelectConfigs[key] = config;

    const input = document.getElementById(config.inputId);
    if (!input || _searchSelectRegistered.has(config.inputId)) return;
    _searchSelectRegistered.add(config.inputId);

    const box = input.closest('.search-box') || input.parentElement;
    let dropdown = document.getElementById(`${config.inputId}-suggest`);
    if (!dropdown) {
        dropdown = document.createElement('div');
        dropdown.className = 'search-suggest-dropdown hidden';
        dropdown.id = `${config.inputId}-suggest`;
        box.appendChild(dropdown);
    }

    function hide() {
        dropdown.classList.add('hidden');
        dropdown.innerHTML = '';
    }

    function showOptions() {
        const cfg = searchSelectConfigs[key];
        const query = input.value.trim().toLowerCase();
        const pool = cfg.getPool() || [];
        const matches = pool.filter(item => {
            if (!query) return true;
            const label = (cfg.getLabel(item) || '').toLowerCase();
            const sub = (cfg.getSub ? (cfg.getSub(item) || '') : '').toLowerCase();
            return label.includes(query) || sub.includes(query);
        }).slice(0, 30);

        if (matches.length === 0) {
            dropdown.innerHTML = `<div class="search-suggest-item" style="cursor:default;"><span class="search-suggest-label" style="color:var(--text-muted); font-weight:normal;">--- ${cfg.emptyText || 'ไม่พบข้อมูลที่ตรงกับคำค้นหา'} ---</span></div>`;
            dropdown.classList.remove('hidden');
            return;
        }

        dropdown.innerHTML = matches.map((item, idx) => {
            const label = cfg.getLabel(item) || '';
            const sub = cfg.getSub ? cfg.getSub(item) : '';
            const badge = cfg.getBadge ? cfg.getBadge(item) : '';
            const subLine = [sub, badge].filter(Boolean).join(' · ');
            return `
                <div class="search-suggest-item" data-idx="${idx}">
                    <span class="search-suggest-label">${label}</span>
                    ${subLine ? `<span class="search-suggest-sub">${subLine}</span>` : ''}
                </div>
            `;
        }).join('');
        dropdown.classList.remove('hidden');

        currentMatches = matches;
        Array.from(dropdown.children).forEach((el, idx) => {
            el.addEventListener('mousedown', (e) => {
                e.preventDefault(); // กันไม่ให้ input blur ก่อนที่ click จะทำงาน
                pick(idx);
            });
        });
    }

    let currentMatches = [];
    function pick(idx) {
        const cfg = searchSelectConfigs[key];
        selectSearchSelectItem(key, cfg.getId(currentMatches[idx]));
        hide();
        input.focus();
    }

    input.addEventListener('input', () => {
        // พิมพ์ทับชื่อที่เลือกไว้เดิม -> ถือว่ายังไม่ได้เลือกใหม่ จนกว่าจะคลิกเลือกจากรายการจริง
        const cfg = searchSelectConfigs[key];
        if (cfg.getValue()) {
            cfg.setValue('');
            if (cfg.onClear) cfg.onClear();
        }
        showOptions();
    });
    input.addEventListener('focus', showOptions);
    input.addEventListener('blur', () => setTimeout(hide, 150));
    attachSuggestKeyboard(input, dropdown, pick, hide, showOptions);
}

// เลือกรายการโดยตรงด้วย id (ใช้ตอนคลิกเลือกจาก dropdown หรือเลือกให้อัตโนมัติจากโค้ด เช่น
// เลือกลูกจ้างแล้วเติมนายจ้างของคนนั้นให้ทันที) — เซ็ตค่าจริง + ข้อความในช่อง + เรียก onSelect เสมอ
function selectSearchSelectItem(key, id) {
    const cfg = searchSelectConfigs[key];
    if (!cfg) return;
    const record = (cfg.getPool() || []).find(item => cfg.getId(item) === id);
    if (!record) return;

    cfg.setValue(id);
    const input = document.getElementById(cfg.inputId);
    if (input) input.value = cfg.getLabel(record) || '';
    if (cfg.onSelect) cfg.onSelect(record);
}

// ล้างค่าที่เลือกไว้ + ข้อความในช่อง (ไม่เรียก onSelect)
function clearSearchSelect(key) {
    const cfg = searchSelectConfigs[key];
    if (!cfg) return;
    cfg.setValue('');
    const input = document.getElementById(cfg.inputId);
    if (input) input.value = '';
    if (cfg.onClear) cfg.onClear();
}

// ตั้งค่าเริ่มต้นตอนเปิดโมดัล (ไม่เรียก onSelect/onClear — ใช้แค่ sync ค่าจริง + ข้อความที่แสดงในช่องให้ตรงกัน
// เช่น ตอนเปิดฟอร์มแก้ไขที่มีค่าเดิมอยู่แล้ว โค้ดที่เรียกเองต่างหากจะจัดการผลข้างเคียง เช่น กรองรายชื่อลูกจ้างตามนายจ้าง)
function presetSearchSelect(key, id) {
    const cfg = searchSelectConfigs[key];
    if (!cfg) return;
    cfg.setValue(id || '');
    const input = document.getElementById(cfg.inputId);
    if (!input) return;
    if (id) {
        const record = (cfg.getPool() || []).find(item => cfg.getId(item) === id);
        input.value = record ? (cfg.getLabel(record) || '') : '';
    } else {
        input.value = '';
    }
}

// ==================== สิทธิ์ตามตำแหน่ง (ยืนยัน 2026-10-02) ====================
// admin = Admin/GM, account_manager = Account Manager, operation_manager = Operation Manager, staff = Staff, client = ลูกค้า
// ฐานข้อมูลบังคับสิทธิ์ซ้ำอีกชั้น (RLS) — ดู supabase/migrations/20261002..._roles_gm_am_om_staff.sql
// แก้สิทธิ์ที่นี่ที่เดียว แล้วใช้ can('...') / canEditJob(j) ทุกจุด
const ROLE_LABELS = {
    admin: 'Admin / GM (สิทธิ์เต็ม)',
    account_manager: 'Account Manager (บิล/การเงิน)',
    operation_manager: 'Operation Manager (งาน/เอกสาร)',
    staff: 'Staff (ทำงานที่ได้รับมอบหมาย)',
    client: 'ลูกค้า/นายจ้าง (เฉพาะข้อมูลตนเอง)'
};
const PERMS = {
    finance:      ['admin', 'account_manager'],                     // บิล รับเงิน มัดจำ รายจ่าย บัญชีธนาคาร ราคามาตรฐาน/ต้นทุน
    voidMoney:    ['admin', 'account_manager'],                     // ยกเลิกใบเสร็จ/การรับเงิน, ถอนยอดออกจากบิล
    commission:   ['admin', 'account_manager'],                     // เห็น/จ่ายค่าคอม Agent
    ops:          ['admin', 'operation_manager', 'staff'],          // เพิ่ม/แก้คนงาน เอกสารคนงาน, เปิดใบงาน
    customers:    ['admin', 'account_manager', 'operation_manager', 'staff'], // เพิ่ม/แก้นายจ้าง + แฟ้มเอกสารนายจ้าง (บัญชีทำได้ แต่คนงานไม่ได้ — owner 2026-10-26)
    assignJobs:   ['admin', 'operation_manager'],                   // มอบหมายผู้รับผิดชอบ + แก้ใบงานทุกใบ
    manageAgents: ['admin', 'account_manager', 'operation_manager'],
    deleteFiles:  ['admin', 'operation_manager'],                   // ลบไฟล์เอกสารในแฟ้ม (Storage)
    driveView:    ['admin', 'account_manager', 'operation_manager', 'staff'], // ปุ่ม "เปิดใน Google Drive" ในแฟ้มคนงาน/นายจ้าง (owner, 2026-10-14)
    admin:        ['admin']                                         // ลบข้อมูล จัดการผู้ใช้ สำรอง/กู้คืน
};

function can(perm) {
    return !!currentUser && (PERMS[perm] || []).includes(currentUser.role);
}

// Staff แก้ได้เฉพาะใบงานที่ตัวเองเปิดหรือได้รับมอบหมาย
function canEditJob(j) {
    if (can('assignJobs')) return true;
    return !!(j && currentUser && currentUser.role === 'staff' && currentUser.id && (j.assignedTo === currentUser.id || j.openedBy === currentUser.id));
}

function getRoleLabel(role) {
    return ROLE_LABELS[role] || ROLE_LABELS.staff;
}

function setupFormPermissions() {
    // ปุ่ม/เมนูที่อยู่ใน index.html ซ่อนด้วย CSS: <body class="perm-no-xxx"> + องค์ประกอบ class="needs-xxx"
    Object.keys(PERMS).forEach(p => document.body.classList.toggle(`perm-no-${p}`, !can(p)));

    const show = (id, on) => { const el = document.getElementById(id); if (el) el.style.display = on ? 'flex' : 'none'; };
    show("btn-add-customer", can('customers'));
    show("btn-add-worker", can('ops'));
    show("btn-add-job", can('ops') || (currentUser && currentUser.role === 'client'));
    show("btn-add-bank", can('finance'));
    show("btn-bulk-import-docs", can('ops'));
    // บัญชีนายจ้าง (Client): เหลือเมนูเดียว "ข้อมูลของบริษัทฉัน" — ซ่อนหน้าภายในทั้งหมด
    // (ตั้งทุกเมนูใหม่ทุกครั้ง เผื่อเครื่องเดียวกันสลับบัญชี client ↔ พนักงาน)
    const isClient = !!currentUser && currentUser.role === 'client';
    document.body.classList.toggle('is-client-portal', isClient);
    const calBtn = document.getElementById('topbar-calendar-btn'); // ปฏิทินทีม: เฉพาะผู้ใช้ภายใน
    if (calBtn) calBtn.classList.toggle('hidden', isClient);
    document.querySelectorAll('.sidebar-menu .menu-item').forEach(item => {
        item.classList.toggle('hidden', item.id === 'menu-client-portal' ? !isClient : isClient);
    });
    if (isClient) return;
    const toggleMenu = (id, on) => { const el = document.getElementById(id); if (el) el.classList.toggle('hidden', !on); };
    toggleMenu("menu-users", can('admin'));
    toggleMenu("menu-backup", can('admin'));
    toggleMenu("menu-expenses", can('finance'));
    toggleMenu("menu-agents", can('manageAgents'));
}

// ==================== AUTHENTICATION ====================
async function handleLogin(e) {
    e.preventDefault();
    const email = document.getElementById("login-username").value.trim();
    const password = document.getElementById("login-password").value;
    const errorEl = document.getElementById("login-error");
    const btn = document.getElementById("btn-login");

    if (window.supabaseAdapter) {
        // Online login using Supabase Auth
        if (btn) {
            btn.disabled = true;
            btn.innerHTML = "<span>" + icon("hourglass") + " กำลังเข้าสู่ระบบ...</span>";
        }
        try {
            const result = await window.supabaseAdapter.login(email, password);
            if (result && result.status === "success") {
                errorEl.style.display = 'none';
                // หมายเหตุ: ไม่เก็บรหัสผ่านไว้ในเครื่องอีกต่อไป — Supabase Auth จัดการ
                // session/token ให้เองผ่าน supabase-js (ปลอดภัยกว่าระบบเดิม)
                currentUser = {
                    id: result.user.id,
                    email: result.user.email,
                    name: result.user.name,
                    role: result.user.role,
                    customer_id: result.user.customer_id,
                    theme: result.user.theme || null,
                    avatarUrl: result.user.avatarUrl || null
                };
                localStorage.setItem("mw_current_user", JSON.stringify(currentUser));
                syncThemeFromAccount(result.user.theme);
                await claimSingleSession(); // ห้ามล็อกอินซ้อน: เครื่องอื่นที่ล็อกอินบัญชีนี้อยู่จะถูกออกจากระบบ
                await initApp();
            } else {
                errorEl.style.display = 'block';
                errorEl.innerText = (result && result.message) || "อีเมลหรือรหัสผ่านไม่ถูกต้อง";
            }
        } catch (err) {
            console.error("Cloud login error:", err);
            errorEl.style.display = 'block';
            errorEl.innerText = "ไม่สามารถเชื่อมต่อ Supabase ได้";
        } finally {
            if (btn) {
                btn.disabled = false;
                btn.innerHTML = "<span>เข้าสู่ระบบ</span>";
            }
        }
        return;
    }

    // ไม่มี Supabase (โหลด supabase-js ไม่ขึ้น) — เดิมมีบัญชีทดลองแบบออฟไลน์ ถอดออกแล้ว (2026-10-13)
    errorEl.style.display = 'block';
    errorEl.innerText = "ไม่สามารถเชื่อมต่อ Supabase ได้ กรุณาตรวจสอบอินเทอร์เน็ตแล้วลองใหม่";
}

// ==================== ห้ามล็อกอินซ้อน (owner, 2026-10-13) ====================
// บัญชีหนึ่งใช้ได้ทีละเครื่อง/เบราว์เซอร์: ล็อกอินที่ไหนทีหลัง ที่เก่าถูกออกจากระบบ
// ล็อกอิน → สุ่มรหัสเซสชัน (localStorage mw_session_id) แล้ว claimSession; หน้าที่เปิดอยู่เช็คทุก 20 วินาที + ตอนกลับมาที่แท็บ
// (แท็บหลายแท็บในเบราว์เซอร์เดียวกันใช้รหัสเดียวกัน — ไม่นับว่าซ้อน)
let sessionGuardTimer = null;

async function claimSingleSession() {
    const id = (crypto.randomUUID && crypto.randomUUID()) || String(Date.now()) + Math.random();
    localStorage.setItem("mw_session_id", id);
    const res = await callCloudAPI("claimSession", { sessionId: id });
    return !!res;
}

async function checkSingleSession() {
    if (!currentUser || !window.supabaseAdapter) return;
    if (window.supabaseAdapter.hasSession && !(await window.supabaseAdapter.hasSession())) {
        logout();
        uiAlert("เซสชันหมดอายุ กรุณาเข้าสู่ระบบใหม่");
        return;
    }
    const mine = localStorage.getItem("mw_session_id");
    const res = await window.supabaseAdapter.callCloudAPI("getActiveSession", {}, currentUser).catch(() => null);
    if (!res || res.status !== "success" || !res.sessionId || !currentUser) return; // เน็ตหลุด/ยังไม่เคยจอง = ไม่ไล่ออก
    if (mine && res.sessionId === mine) return;
    logout();
    uiAlert("บัญชีนี้ถูกเข้าสู่ระบบจากเครื่องหรือเบราว์เซอร์อื่น จึงออกจากระบบที่นี่ให้อัตโนมัติ\n(ใช้ได้ทีละเครื่อง ถ้าไม่ใช่คุณ ให้เปลี่ยนรหัสผ่าน)");
}

async function startSessionGuard() {
    stopSessionGuard();
    if (!window.supabaseAdapter || !currentUser) return;
    if (!localStorage.getItem("mw_session_id")) await claimSingleSession(); // ล็อกอินค้างไว้จากก่อนมีระบบนี้
    sessionGuardTimer = setInterval(checkSingleSession, 20000);
    startOnlinePresence();
}

function stopSessionGuard() {
    if (sessionGuardTimer) clearInterval(sessionGuardTimer);
    sessionGuardTimer = null;
    stopOnlinePresence();
}

// ==================== ใครออนไลน์อยู่ (หน้าจัดการบัญชีผู้ใช้งาน) ====================
// Supabase Realtime Presence: ทุกคนที่เปิดแอปอยู่ join ช่อง 'online-users' ด้วย id บัญชีจริง (ไม่ใช่ id ตอน "ดูแบบผู้ใช้")
// ปิดแท็บ/เน็ตหลุด = หลุดจากรายชื่อเอง ไม่ต้องเก็บอะไรในฐานข้อมูล — renderUsers แสดงจุดเขียว "ออนไลน์"
let onlineChannel = null;
let onlineUserIds = new Set();

function startOnlinePresence() {
    stopOnlinePresence();
    const sb = window.supabaseAdapter && window.supabaseAdapter.client;
    if (!sb || !sb.channel || !currentUser) return;
    const myId = currentUser.id;
    const amAdmin = currentUser.role === 'admin';
    let joinedAt = 0; // คนที่ออนไลน์อยู่ก่อนเราเข้า ก็ส่ง join มาตอนต่อช่องใหม่ๆ — ไม่ต้องแจ้ง
    const ch = sb.channel('online-users', { config: { presence: { key: myId } } });
    ch.on('presence', { event: 'sync' }, () => {
        onlineUserIds = new Set(Object.keys(ch.presenceState()));
        const tbody = document.getElementById("users-tbody");
        if (tbody && tbody.offsetParent) renderUsers();
    }).on('presence', { event: 'join' }, ({ key, currentPresences }) => {
        // Admin เท่านั้น: มีคนเพิ่งออนไลน์ (แท็บแรกของเขา — เปิดแท็บเพิ่มไม่นับ) → แทปเด้งขึ้นมาแล้วหายไป (owner 2026-10-22)
        if (!amAdmin || key === myId || !joinedAt || Date.now() - joinedAt < 4000) return;
        if (currentPresences && currentPresences.length) return;
        const u = users.find(x => x.id === key);
        if (u) showOnlineToast(u);
    }).subscribe(status => {
        if (status === 'SUBSCRIBED') { joinedAt = Date.now(); ch.track({ since: new Date().toISOString() }); }
    });
    onlineChannel = ch;
}

function showOnlineToast(u) {
    let stack = document.getElementById("online-toast-stack");
    if (!stack) {
        stack = document.createElement("div");
        stack.id = "online-toast-stack";
        document.body.appendChild(stack);
    }
    const el = document.createElement("div");
    el.className = "online-toast";
    el.title = "เปิดหน้าจัดการบัญชีผู้ใช้งาน";
    el.innerHTML = `<span class="user-avatar user-avatar-sm is-online">${userAvatarHtml(u)}</span>
        <div><div class="online-toast-name">${escapeHtml(u.name || '-')}</div><div class="online-toast-sub">ออนไลน์แล้ว · ${escapeHtml(getRoleLabel(u.role))}</div></div>`;
    el.onclick = () => { switchView('users'); el.remove(); };
    stack.appendChild(el);
    requestAnimationFrame(() => el.classList.add("is-in"));
    setTimeout(() => { el.classList.remove("is-in"); setTimeout(() => el.remove(), 300); }, 4500);
}

function stopOnlinePresence() {
    if (onlineChannel) {
        const sb = window.supabaseAdapter && window.supabaseAdapter.client;
        try { if (sb) sb.removeChannel(onlineChannel); } catch (e) { /* ช่องปิดไปแล้ว */ }
    }
    onlineChannel = null;
    onlineUserIds = new Set();
}

document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible' && sessionGuardTimer) checkSingleSession(); });

function logout() {
    stopSessionGuard();
    localStorage.removeItem("mw_session_id");
    if (viewAsReal) { viewAsReal = null; document.body.classList.remove('is-viewing-as'); const vb = document.getElementById('view-as-bar'); if (vb) vb.remove(); }
    localStorage.removeItem("mw_current_user");
    currentUser = null;
    calendarNotes = null; calendarNoteList = []; // โน้ตทีมไม่ค้างไปถึงบัญชีถัดไป (เช่น บัญชีนายจ้าง)
    closeNotificationPanel();
    updateNotificationBell(); // ไม่มีผู้ใช้ = 0 → ซ่อนตัวเลข ไม่ให้ค้างไปถึงบัญชีที่ login ถัดไป
    hideMainLayout();
    showLoginView();
    showToast("ออกจากระบบเรียบร้อยแล้ว", "success");
}

function showLoginView() {
    document.getElementById("login-view").classList.add("active");
    document.getElementById("login-view").classList.remove("hidden");
}

function showResetPasswordView() {
    document.getElementById("login-view").classList.remove("active");
    document.getElementById("login-view").classList.add("hidden");
    document.getElementById("reset-password-view").classList.add("active");
    document.getElementById("reset-password-view").classList.remove("hidden");
}

async function handleResetPassword(e) {
    e.preventDefault();
    const newPassword = document.getElementById("reset-password-new").value;
    const confirmPassword = document.getElementById("reset-password-confirm").value;
    const errorEl = document.getElementById("reset-password-error");
    const btn = document.getElementById("btn-reset-password");

    if (newPassword.length < 8) {
        errorEl.innerText = "รหัสผ่านต้องมีอย่างน้อย 8 ตัวอักษร";
        errorEl.style.display = 'block';
        return;
    }
    if (newPassword !== confirmPassword) {
        errorEl.innerText = "รหัสผ่านทั้งสองช่องไม่ตรงกัน";
        errorEl.style.display = 'block';
        return;
    }

    if (btn) {
        btn.disabled = true;
        btn.innerHTML = "<span>" + icon("hourglass") + " กำลังบันทึก...</span>";
    }
    try {
        const result = await window.supabaseAdapter.updatePassword(newPassword);
        if (result.status === "success") {
            await window.supabaseAdapter.signOut();
            // Drop the recovery token from the URL so a refresh doesn't loop back here
            history.replaceState(null, "", window.location.pathname + window.location.search);
            document.getElementById("reset-password-view").classList.remove("active");
            document.getElementById("reset-password-view").classList.add("hidden");
            showLoginView();
            showToast("ตั้งรหัสผ่านใหม่สำเร็จ กรุณาเข้าสู่ระบบอีกครั้ง", "success");
        } else {
            errorEl.innerText = result.message || "ไม่สามารถตั้งรหัสผ่านใหม่ได้";
            errorEl.style.display = 'block';
        }
    } catch (err) {
        console.error("Reset password error:", err);
        errorEl.innerText = "เกิดข้อผิดพลาด กรุณาลองอีกครั้ง";
        errorEl.style.display = 'block';
    } finally {
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = "<span>บันทึกรหัสผ่านใหม่</span>";
        }
    }
}

function hideLoginView() {
    document.getElementById("login-view").classList.remove("active");
    document.getElementById("login-view").classList.add("hidden");
}

function showMainLayout() {
    document.getElementById("main-layout").classList.remove("hidden");
}

function hideMainLayout() {
    document.getElementById("main-layout").classList.add("hidden");
}

// ==================== NAVIGATION / ROUTING ====================
// ==================== พอร์ทัลนายจ้าง (บัญชี Client) ====================
// นายจ้าง login ด้วยบัญชีของตัวเอง (role = client, profiles.customer_id) — ฐานข้อมูลกรองให้เห็นเฉพาะข้อมูลของตัวเอง (RLS)
// แท็บ: คนงานของฉัน (+เอกสารลูกจ้าง) / งานที่แจ้ง (เลือกเดือน) / ยอดค้างชำระ / ใบเสร็จรับเงิน
// ไม่แสดงเอกสารของนายจ้างเอง (เจ้าของระบบกำหนด 2026-10-02)
let clientPortalTab = 'workers';
const WORKER_STATUS_LABELS = { active: 'ปกติ', pending_register: 'รอขึ้นทะเบียน', archived: 'แจ้งออก/พ้นสภาพ' };

function clientCustomerId() {
    return (currentUser && currentUser.customer_id && currentUser.customer_id !== 'ALL') ? currentUser.customer_id : (customers[0] || {}).id;
}

function switchClientPortalTab(tab) {
    clientPortalTab = tab;
    document.querySelectorAll('[data-portal-tab]').forEach(b => {
        b.classList.toggle('btn-gold', b.dataset.portalTab === tab);
        b.classList.toggle('btn-outline', b.dataset.portalTab !== tab);
    });
    renderClientPortal();
    replayPageTransition(document.getElementById("client-portal-body"));
}

// เล่นแอนิเมชันเปลี่ยนหน้า (Fade-up, .page-transition-in ใน styles.css) ซ้ำกับกล่องที่ไม่ได้ถูกซ่อน/แสดง แต่เปลี่ยนเนื้อหาด้วย innerHTML
function replayPageTransition(el) {
    if (!el) return;
    el.classList.remove('page-transition-in');
    void el.offsetWidth;
    el.classList.add('page-transition-in');
}

function renderClientPortal() {
    const custId = clientCustomerId();
    const cust = customers.find(c => c.id === custId);
    const myWorkers = workers.filter(w => w.employerId === custId && w.status !== 'deleted');
    const myJobs = jobs.filter(j => j.customerId === custId);
    const myInvoices = invoices.filter(i => i.customerId === custId && i.status !== 'void');
    const outstanding = round2(myInvoices.filter(i => i.status === 'issued' || i.status === 'partial').reduce((s, i) => s + invoiceBalance(i), 0));
    const head = document.getElementById("client-portal-head");
    if (head) head.innerHTML = `
        <div class="cp-company"><h3>${icon('building')} ${escapeHtml(cust ? cust.companyName : 'บริษัทของฉัน')}</h3>
            <span class="text-muted">${cust && cust.taxId ? `เลขผู้เสียภาษี ${escapeHtml(cust.taxId)}` : ''}</span></div>
        <div class="cp-stats">
            <div><span>คนงานปัจจุบัน</span><strong>${myWorkers.filter(w => w.status !== 'archived').length}</strong></div>
            ${myWorkers.some(workerNeedsNotifyEntry) ? `<div class="is-due"><span>รอแจ้งเข้า</span><strong>${myWorkers.filter(workerNeedsNotifyEntry).length}</strong></div>` : ''}
            <div><span>งานที่ยังไม่ปิด</span><strong>${myJobs.filter(j => isJobStatusOpen(j.status)).length}</strong></div>
            <div class="${outstanding > 0 ? 'is-due' : ''}"><span>ยอดค้างชำระ</span><strong>${fmtMoney(outstanding)}</strong></div>
        </div>`;

    const body = document.getElementById("client-portal-body");
    if (!body) return;
    const dueBadge = document.getElementById('cp-renewal-badge');
    if (dueBadge) dueBadge.textContent = clientRenewalDue(myWorkers).length || '';
    if (clientPortalTab === 'workers') body.innerHTML = renderClientWorkersTab(myWorkers);
    else if (clientPortalTab === 'renewal') body.innerHTML = renderClientRenewalTab(myWorkers);
    else if (clientPortalTab === 'register') body.innerHTML = renderClientRegisterTab(myWorkers);
    else if (clientPortalTab === 'jobs') body.innerHTML = renderClientJobsTab(myJobs.filter(j => !isSystemJob(j))); // งานต่ออายุอยู่แท็บ "ต่ออายุ"
    else if (clientPortalTab === 'balance') body.innerHTML = renderClientBalanceTab(myInvoices, custId);
    else body.innerHTML = renderClientReceiptsTab(myInvoices, custId);
    applySavedCollapse(body); // กลุ่มที่เคยยุบไว้ ยุบกลับหลังวาดใหม่ (พิมพ์ค้นหา/เปลี่ยนตัวกรอง)
}

// ==================== พอร์ทัล: แท็บ "ต่ออายุ" (owner 2026-10-20) ====================
// นายจ้างเลือกคนงานที่ถึงรอบ (ใบอนุญาตเหลือ ≤ 60 วัน) แล้วส่งคำขอ → รอบเริ่มทันที (RPC client_start_renewals:
// สร้างรอบ + ใบงานเก็บเงินเบื้องหลัง, ป้าย "ลูกค้าเปิดงาน" ฝั่งเจ้าหน้าที่) — ยกเลิกเองได้ถ้ายังไม่ตรวจสุขภาพและยังไม่ออกบิล
const cpRenewalPick = new Set();
const cpRenewalBook = new Map();
const clientRenewalDue = (myWorkers) => myWorkers.filter(w => w.status !== 'archived' && w.status !== 'deleted' && w.permitExpiry
    && renewalDaysLeft(w.permitExpiry) !== null && renewalDaysLeft(w.permitExpiry) <= RENEWAL_DUE_DAYS && !renewalActiveOf(w.id) && !renewalExternalOf(w.id));
const clientRenewalBilled = (r) => renewalJobsOf(r).some(j => getJobInvoice(j) || isJobNoCharge(j));

// ล็อกเอกสารต่ออายุจนกว่าจ่าย (owner 2026-10-20): ไฟล์ที่ขั้นต่าง ๆ ของรอบแนบไว้ (ใบคำขอ ใบเสร็จ ใบแทน Smart card เล่มใหม่)
// ลูกค้าไม่เห็นในแฟ้มคนงาน จนกว่าใบงานเก็บเงินของรอบนั้นปลดล็อกทุกใบ (กติกาเดียวกับเอกสารปิดงาน — clientJobDocsUnlocked)
// รอบที่ยกเลิกแล้ว (ใบงานถูกลบ) ไม่ล็อก; Drive ใช้กติกาเดียวกันใน drive-backup
function clientLockedRenewalUrls() {
    const out = new Set();
    if (!currentUser || currentUser.role !== 'client' || !renewalList) return out;
    renewalList.forEach(r => {
        const js = renewalJobsOf(r);
        if (!js.length || js.every(clientJobDocsUnlocked)) return;
        Object.values(r.steps || {}).forEach(s => { if (s && s.url) out.add(s.url); });
    });
    return out;
}

function renderClientRenewalTab(myWorkers) {
    if (renewalList === null) { loadRenewals(true); return `<div class="cp-card"><p class="text-muted">กำลังโหลด…</p></div>`; }
    const due = clientRenewalDue(myWorkers).sort((a, b) => String(permitExpiryKey(a)).localeCompare(String(permitExpiryKey(b))));
    due.forEach(w => { if (!cpRenewalBook.has(w.id)) cpRenewalBook.set(w.id, renewalSuggestBook(w)); });
    [...cpRenewalPick].forEach(id => { if (!due.some(w => w.id === id)) cpRenewalPick.delete(id); });
    const mine = new Set(myWorkers.map(w => w.id));
    const rounds = (renewalList || []).filter(r => mine.has(r.workerId) && r.kind !== 'registration');
    const active = rounds.filter(r => r.status === 'active');
    const done = rounds.filter(r => r.status === 'done' || r.status === 'external')
        .sort((a, b) => String(b.doneAt || b.startedAt).localeCompare(String(a.doneAt || a.startedAt))).slice(0, 20);
    const wOf = r => workers.find(w => w.id === r.workerId) || {};

    const dueRows = due.map(w => `<div class="cp-rn-row${cpRenewalPick.has(w.id) ? ' is-selected' : ''}">
        <input type="checkbox" ${cpRenewalPick.has(w.id) ? 'checked' : ''} onchange="toggleClientRenewalPick(['${w.id}'], this.checked)" title="เลือก ${escapeHtml(workerFullName(w))}">
        <div class="renewal-avatar"><img src="${w.photo ? escapeHtml(w.photo) : WORKER_AVATAR_PLACEHOLDER}" alt="" loading="lazy"></div>
        <div class="cp-rn-name"><strong>${escapeHtml(workerFullName(w))}</strong><small class="text-muted">${escapeHtml(w.workerUid || '')}</small></div>
        <span>${renewalExpiryCell(w.permitExpiry)}</span>
        <span class="text-muted">พาสปอร์ตถึง ${w.passportExpiry ? formatThaiDate(w.passportExpiry) : '-'}</span>
        <label class="rn-book-pick" title="ทำพาสปอร์ต/CI เล่มใหม่ด้วย (ระบบติ๊กให้เมื่อเล่มจะหมดก่อนใบอนุญาตใหม่)"><input type="checkbox" ${cpRenewalBook.get(w.id) ? 'checked' : ''} onchange="cpRenewalBook.set('${w.id}', this.checked); renderClientPortal()"> ทำเล่มด้วย</label>
    </div>`).join('');

    const activeRows = active.map(r => {
        const owe = renewalJobsOf(r).map(getJobInvoice).filter(Boolean).reduce((s, inv) => s + invoiceBalance(inv), 0);
        const pill = owe > 0 ? `<span class="badge badge-danger">ค้างชำระ ${fmtMoney(owe)}</span>`
            : !Object.keys(r.steps).length ? '<span class="badge badge-gold">เริ่มแล้ว</span>' : '<span class="badge badge-warning">กำลังดำเนินการ</span>';
        const canCancel = !r.steps.medical && !clientRenewalBilled(r);
        // ทำเล่มที่อื่น: รอบนี้ติ๊กทำเล่มไว้ เล่มยังไม่ได้ทำ และค่าทำเล่มยังไม่ออกบิล
        const canBookExt = r.withBook && !r.steps.book && !r.steps.bookExternal
            && !renewalJobsOf(r).some(j => j.jobType === RENEWAL_BOOK_JOB_TYPE && (getJobInvoice(j) || isJobNoCharge(j)));
        return `<div class="cp-rn-row cp-rn-active">
            <div class="cp-rn-name"><strong>${escapeHtml(workerFullName(wOf(r)))}</strong><small class="rn-uid">${escapeHtml(wOf(r).workerUid || '')}</small><small class="text-muted">หมด ${r.oldPermitExpiry ? formatThaiDate(r.oldPermitExpiry) : '-'}${r.withBook && !renewalSplitBook(r) ? (r.steps.bookExternal ? ' · ทำเล่มที่อื่น' : ' · ทำเล่มด้วย') : ''}</small></div>
            <div class="rn-arow-progress"><div class="rn-rings">${renewalRingHtml(r, 'main')}${renewalSplitBook(r) ? renewalRingHtml(r, 'book') : ''}</div></div>
            <span class="text-muted">${r.appointmentDate ? `นัดรับบัตร ${formatThaiDate(r.appointmentDate)}` : 'ยังไม่นัด'}${r.steps.bookAppt && r.steps.bookAppt.date ? `<small class="rn-book-appt">นัดทำเล่ม ${formatThaiDate(r.steps.bookAppt.date)}</small>` : ''}</span>
            <span>${pill}</span>
            <span class="cp-rn-btns">${canBookExt ? `<button type="button" class="btn btn-sm btn-outline" onclick="clientBookExternal('${r.id}')" title="เล่มทำที่อื่น (ไม่คิดค่าทำเล่ม)">ทำเล่มที่อื่น</button>` : ''}
                ${canCancel ? `<button type="button" class="btn btn-sm btn-outline" onclick="clientMarkExternal(['${r.workerId}'])" title="แจ้งว่าไปต่อใบอนุญาตที่อื่น (ได้เฉพาะก่อนตรวจสุขภาพ)">ต่อที่อื่นแล้ว</button>
                <button type="button" class="btn btn-sm btn-outline" onclick="clientCancelRenewal('${r.id}')" title="ยกเลิกคำขอต่ออายุ (ได้เฉพาะก่อนตรวจสุขภาพ)">ยกเลิก</button>` : ''}</span>
        </div>`;
    }).join('');

    const doneRows = done.map(r => {
        const ext = r.status === 'external';
        const newExp = r.newPermitExpiry || (ext && !renewalExternalPending(r) ? permitExpiryKey(wOf(r)) : null);
        return `<div class="cp-rn-row cp-rn-done">
        <div class="cp-rn-name"><strong>${escapeHtml(workerFullName(wOf(r)))}</strong>${ext ? '<span class="rn-ext-tag">ต่อที่อื่น</span>' : ''}</div>
        <span class="text-muted">เดิม ${r.oldPermitExpiry ? formatThaiDate(r.oldPermitExpiry) : '-'}</span>
        <span>${newExp ? `ใบอนุญาตใหม่ถึง <strong>${formatThaiDate(newExp)}</strong>` : '<span class="text-muted">รอข้อมูลใบอนุญาตใหม่</span>'}</span>
        <span class="text-muted">${ext ? `แจ้ง ${formatThaiDate(String(r.startedAt || '').slice(0, 10))}` : `เสร็จ ${r.doneAt ? formatThaiDate(String(r.doneAt).slice(0, 10)) : '-'}`}</span>
    </div>`;
    }).join('');

    const allPicked = due.length > 0 && due.every(w => cpRenewalPick.has(w.id));
    const nBook = [...cpRenewalPick].filter(id => cpRenewalBook.get(id)).length;
    return `<div class="cp-card cp-rn-card">
            <div class="cp-rn-head"><div><h3>ถึงรอบต่ออายุ ${due.length ? `<span class="text-muted">${due.length} คน</span>` : ''}</h3>
                <small class="text-muted">ใบอนุญาตทำงานจะหมดภายใน 2 เดือน — เลือกคนที่ต้องการต่ออายุ แล้วกดส่งคำขอ</small></div>
                ${due.length ? `<div class="cp-rn-actions">
                    <div class="cp-rn-btns">
                    <button type="button" class="btn btn-gold" ${cpRenewalPick.size ? '' : 'disabled'} onclick="clientSubmitRenewals()" title="ส่งคำขอต่ออายุของคนงานที่เลือก">ส่งคำขอต่ออายุ${cpRenewalPick.size ? ` ${cpRenewalPick.size} คน` : ''}${nBook ? ` · ทำเล่ม ${nBook}` : ''}</button>
                    <button type="button" class="btn btn-outline" ${cpRenewalPick.size ? '' : 'disabled'} onclick="clientMarkExternal([...cpRenewalPick])" title="แจ้งว่าคนงานที่เลือกไปต่อใบอนุญาตที่อื่นแล้ว">ต่อที่อื่นแล้ว${cpRenewalPick.size ? ` ${cpRenewalPick.size} คน` : ''}</button>
                    </div>
                    <label class="rn-book-pick"><input type="checkbox" ${allPicked ? 'checked' : ''} onchange="toggleClientRenewalPick(${escapeHtml(JSON.stringify(due.map(w => w.id)))}, this.checked)"> เลือกทั้งหมด</label>
                </div>` : ''}</div>
            ${dueRows || '<p class="text-muted cp-rn-empty">ยังไม่มีคนงานที่ถึงรอบต่ออายุ</p>'}
        </div>
        <div class="cp-card cp-rn-card"><div class="cp-rn-head"><h3>กำลังดำเนินการ ${active.length ? `<span class="text-muted">${active.length} คน</span>` : ''}</h3></div>
            ${activeRows || '<p class="text-muted cp-rn-empty">ไม่มีรายการ</p>'}</div>
        ${done.length ? `<div class="cp-card cp-rn-card"><div class="cp-rn-head"><h3>เสร็จแล้ว / ต่อที่อื่น</h3></div>${doneRows}</div>` : ''}`;
}

// ==================== พอร์ทัล: แท็บ "ขึ้นทะเบียน" (owner 2026-10-20) ====================
// นายจ้างส่งรายชื่อคนงานรอขึ้นทะเบียนเอง (openRegWorkerModal โหมดลูกค้า → RPC client_save_pending_worker)
// แก้ได้จนกว่าเจ้าหน้าที่จะนำเข้ารอบ มติ ครม. — หลังจากนั้นดูอย่างเดียว
function renderClientRegisterTab(myWorkers) {
    if (registrationRounds === null) { loadRegistrationRounds().then(renderClientPortal); }
    const pool = myWorkers.filter(regInPool);
    const inRound = myWorkers.filter(w => w.registrationRoundId && w.status === 'pending_register');
    const done = myWorkers.filter(regDone);
    const roundName = id => { const r = (registrationRounds || []).find(x => x.id === id); return r ? regRoundLabel(r) : 'มติ ครม.'; };
    const row = (w, right) => `<div class="cp-rn-row cp-reg-row">
        <div class="renewal-avatar"><img src="${w.photo ? escapeHtml(w.photo) : WORKER_AVATAR_PLACEHOLDER}" alt="" loading="lazy"></div>
        <div class="cp-rn-name"><strong>${escapeHtml(workerFullName(w))}</strong><small class="text-muted">${escapeHtml(w.nationality || '')}${w.dob ? ` · เกิด ${formatThaiDate(w.dob)}` : ''}</small></div>
        <div class="reg-chips">${right}</div>
    </div>`;
    const poolRows = pool.map(w => row(w, regChipsHtml(w)
        + `<button type="button" class="btn btn-sm btn-outline" onclick="openRegWorkerModal('${w.id}')" title="แก้ไขข้อมูลหรือแนบไฟล์เพิ่ม">แก้ไข</button>`)).join('');
    // ความคืบหน้า (แถบขั้นตอน ดูอย่างเดียว) + ยอดค้างของรายการขึ้นทะเบียน — เหมือนแท็บต่ออายุ
    const roundRows = inRound.map(w => {
        const r = regActiveRoundOf(w.id);
        if (!r) return row(w, `<span class="badge badge-warning">อยู่ในรอบ ${escapeHtml(roundName(w.registrationRoundId))} · เจ้าหน้าที่กำลังดำเนินการ</span>`);
        const next = renewalNextStep(r);
        const nextKey = (next || {}).key;
        const bar = renewalAllStepsOf(r).map(s => `<span class="rn-seg ${r.steps[s.key] ? (r.steps[s.key].skipped ? 'is-ext' : 'is-done') : s.key === nextKey ? 'is-next' : ''}${s.key.startsWith('book') ? ' is-book' : ''}" title="${escapeHtml(s.label)}"></span>`).join('');
        const owe = renewalJobsOf(r).map(getJobInvoice).filter(Boolean).reduce((sum, inv) => sum + invoiceBalance(inv), 0);
        return row(w, `<div class="rn-arow-progress cp-reg-progress"><div class="rn-bar">${bar}</div><small class="text-muted">${escapeHtml(roundName(r.registrationRoundId))} · ${next ? `รอ${escapeHtml(next.label)}` : 'ครบทุกขั้น'}${r.appointmentDate ? ` · นัด ${formatThaiDate(r.appointmentDate)}` : ''}</small></div>
            ${owe > 0 ? `<span class="badge badge-danger">ค้างชำระ ${fmtMoney(owe)}</span>` : ''}`);
    }).join('');
    const doneRows = done.map(w => row(w, `<span class="badge badge-success">ขึ้นทะเบียนแล้ว${w.workerUid ? ` · ${escapeHtml(w.workerUid)}` : ''}</span>`)).join('');
    return `<div class="cp-card cp-rn-card">
            <div class="cp-rn-head"><div><h3>รายชื่อรอขึ้นทะเบียน ${pool.length ? `<span class="text-muted">${pool.length} คน</span>` : ''}</h3>
                <small class="text-muted">ส่งรายชื่อไว้ได้ทั้งปี · เมื่อรัฐเปิดรับ เจ้าหน้าที่จะนำเข้ารอบและแจ้งค่าบริการ · ใส่รูปถ่าย บัตรประชาชนหน้า-หลัง ชื่อ และวันเกิดให้ครบ</small></div>
                <button type="button" class="btn btn-gold" onclick="openRegWorkerModal()" title="ส่งรายชื่อคนงานรอขึ้นทะเบียน">${icon('plus')} ส่งรายชื่อคนงาน</button></div>
            ${poolRows || '<p class="text-muted cp-rn-empty">ยังไม่มีรายชื่อ — กด "ส่งรายชื่อคนงาน"</p>'}
        </div>
        ${inRound.length ? `<div class="cp-card cp-rn-card"><div class="cp-rn-head"><h3>กำลังขึ้นทะเบียน <span class="text-muted">${inRound.length} คน</span></h3></div>${roundRows}</div>` : ''}
        ${done.length ? `<div class="cp-card cp-rn-card"><div class="cp-rn-head"><h3>ขึ้นทะเบียนแล้ว</h3></div>${doneRows}</div>` : ''}`;
}

function toggleClientRenewalPick(ids, on) {
    ids.forEach(id => { if (on) cpRenewalPick.add(id); else cpRenewalPick.delete(id); });
    renderClientPortal();
}

async function clientSubmitRenewals() {
    const list = [...cpRenewalPick].map(id => workers.find(w => w.id === id)).filter(Boolean);
    if (!list.length) return;
    const note = await uiPrompt(`ส่งคำขอต่ออายุ ${list.length} คน — เจ้าหน้าที่จะได้รับแจ้งทันที และติดต่อกลับเรื่องเอกสารและค่าบริการ ข้อความถึงเจ้าหน้าที่ (ไม่ใส่ก็ได้)`, {
        title: 'ส่งคำขอต่ออายุ', okText: 'ส่งคำขอ', placeholder: 'เช่น ให้ติดต่อคุณสมชาย 08x-xxx-xxxx',
        summary: list.map(w => ({ label: workerFullName(w), value: `ถึง ${formatThaiDate(w.permitExpiry)}${cpRenewalBook.get(w.id) ? ' · ทำเล่มด้วย' : ''}` }))
    });
    if (note === null) return;
    const res = await callCloudAPI("clientStartRenewals", {
        rows: list.map(w => ({ worker_id: w.id, with_book: !!cpRenewalBook.get(w.id) })), note
    });
    if (!res || res.status !== "success") { showToast("❌ ส่งคำขอไม่สำเร็จ: " + (res && res.message ? res.message : "กรุณาลองใหม่"), "danger"); return; }
    list.forEach(w => cpRenewalPick.delete(w.id));
    await loadData(); // ดึงรอบ + ใบงานเก็บเงินที่ฐานข้อมูลสร้างให้
    await loadRenewals(true);
    showUploadPill('ok', `ส่งคำขอต่ออายุ ${res.rows.length} คนแล้ว`, 'ดูความคืบหน้าได้ที่แท็บ "ต่ออายุ"');
    renderClientPortal();
}

// ลูกค้าแจ้ง "ต่อที่อื่นแล้ว" (คนงานที่ถึงรอบ หรือรอบที่ยังไม่ตรวจสุขภาพ/ยังไม่ออกบิล) — RPC client_mark_external
async function clientMarkExternal(workerIds) {
    const list = workerIds.map(id => workers.find(w => w.id === id)).filter(Boolean);
    if (!list.length) return;
    const note = await uiPrompt(`แจ้งว่า ${list.length} คนไปต่อใบอนุญาตที่อื่นแล้ว — ไม่มีค่าบริการจากเรา เจ้าหน้าที่จะขอสำเนาใบอนุญาตใหม่ภายหลัง ข้อความถึงเจ้าหน้าที่ (ไม่ใส่ก็ได้)`, {
        title: 'ต่อที่อื่นแล้ว', okText: 'แจ้งต่อที่อื่น', placeholder: 'เช่น ต่อกับบริษัทนายหน้า …',
        summary: list.map(w => ({ label: workerFullName(w), value: `ใบอนุญาตถึง ${formatThaiDate(w.permitExpiry)}` }))
    });
    if (note === null) return;
    const res = await callCloudAPI("clientMarkExternal", { workerIds: list.map(w => w.id), note });
    if (!res || res.status !== "success") { showToast("❌ แจ้งไม่สำเร็จ: " + (res && res.message ? res.message : "กรุณาลองใหม่"), "danger"); return; }
    list.forEach(w => cpRenewalPick.delete(w.id));
    await loadData(); // รายการรอออกบิลที่ถูกลบในฐานข้อมูล
    await loadRenewals(true);
    showUploadPill('ok', `แจ้งต่อที่อื่น ${res.rows.length} คนแล้ว`);
    renderClientPortal();
}

// ลูกค้าแจ้ง "ทำเล่มที่อื่น" ในรอบที่ติ๊กทำเล่มไว้ — RPC client_book_external
async function clientBookExternal(id) {
    const r = (renewalList || []).find(x => x.id === id);
    const w = r && workers.find(x => x.id === r.workerId);
    if (!r) return;
    const ok = await uiConfirm(`เล่มของ ${w ? workerFullName(w) : 'คนงานนี้'} ทำที่อื่น? ไม่มีค่าทำเล่มจากเรา เจ้าหน้าที่จะขอข้อมูลเล่มใหม่ภายหลัง`, {
        title: 'ทำเล่มที่อื่น', okText: 'ทำเล่มที่อื่น', danger: false
    });
    if (!ok) return;
    const res = await callCloudAPI("clientBookExternal", { id });
    if (!res || res.status !== "success") { showToast("❌ แจ้งไม่สำเร็จ: " + (res && res.message ? res.message : "กรุณาลองใหม่"), "danger"); return; }
    jobs = jobs.filter(j => !(j.batchId === `renewal-${id}` && j.jobType === RENEWAL_BOOK_JOB_TYPE));
    Object.assign(r, renewalFromRow(res.row));
    saveData();
    showUploadPill('ok', 'แจ้งทำเล่มที่อื่นแล้ว');
    renderClientPortal();
}

async function clientCancelRenewal(id) {
    const r = (renewalList || []).find(x => x.id === id);
    const w = r && workers.find(x => x.id === r.workerId);
    if (!r) return;
    const ok = await uiConfirm(`ยกเลิกคำขอต่ออายุของ ${w ? workerFullName(w) : 'คนงานนี้'}?`, { title: 'ยกเลิกคำขอต่ออายุ', okText: 'ยกเลิกคำขอ', danger: true });
    if (!ok) return;
    const res = await callCloudAPI("clientCancelRenewal", { id });
    if (!res || res.status !== "success") { showToast("❌ ยกเลิกไม่สำเร็จ: " + (res && res.message ? res.message : "กรุณาลองใหม่"), "danger"); return; }
    jobs = jobs.filter(j => j.batchId !== `renewal-${id}`);
    Object.assign(r, renewalFromRow(res.row));
    saveData();
    showUploadPill('ok', 'ยกเลิกคำขอต่ออายุแล้ว');
    renderClientPortal();
}

// ตัวกรองในพอร์ทัลนายจ้าง (owner, 2026-10-14) — เก็บค่าไว้ในตัวแปร ไม่หายตอนวาดแท็บใหม่
const cpFilters = { workerStatus: '', workerNat: '', jobStatus: '', jobType: '' };
function setClientPortalFilter(key, value) {
    cpFilters[key] = value;
    renderClientPortal();
}

// สถานะเอกสารคนงานในพอร์ทัล (ใช้ทั้งป้ายในตารางและตัวกรอง)
function clientWorkerDocState(w) {
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const daysTo = (d) => d ? Math.ceil((d - today) / 86400000) : null;
    const pd = daysTo(safeParseDate(w.passportExpiry)), wd = daysTo(safeParseDate(w.permitExpiry));
    if (w.status === 'archived') return 'archived';
    if (w.status === 'pending_register') return 'pending';
    if ((pd !== null && pd < 0) || (wd !== null && wd < 0)) return 'expired';
    if ((pd !== null && pd <= 180) || (wd !== null && wd <= 60)) return 'soon';
    return 'ok';
}
const CP_WORKER_STATES = {
    ok: { label: 'ปกติ', cls: 'badge-success' },
    soon: { label: 'ใกล้หมดอายุ', cls: 'badge-warning' },
    expired: { label: 'หมดอายุ', cls: 'badge-danger' },
    pending: { label: 'รอขึ้นทะเบียน', cls: 'badge-gold' },
    archived: { label: 'พ้นสภาพ/แจ้งออก', cls: 'cp-badge-archived' }
};

// ปุ่มยุบ/กางทุกกลุ่มในแท็บพอร์ทัล
function cpCollapseButtons() {
    const body = "document.getElementById('client-portal-body')";
    return `<div class="cp-collapse-btns">
        <button type="button" class="btn btn-sm btn-outline" onclick="setPanelsCollapsed(${body}, true)" title="ยุบทุกกลุ่มให้เหลือแค่หัวข้อ">${icon('chevronUp')} ยุบทั้งหมด</button>
        <button type="button" class="btn btn-sm btn-outline" onclick="setPanelsCollapsed(${body}, false)" title="กางทุกกลุ่ม">${icon('chevronDown')} กางทั้งหมด</button>
    </div>`;
}

// พอร์ทัลนายจ้าง: ดับเบิลคลิกแถวคนงาน → ป๊อปอัปข้อมูลคนงานทั้งหมด (ดูอย่างเดียว แก้ไม่ได้)
// หน้าตาเดียวกับหน้าต่างตรวจสอบก่อนบันทึก (showUiDialog + card + summary) พร้อมรูปคนงาน
function openClientWorkerView(workerId) {
    const w = workers.find(x => x.id === workerId);
    if (!w) return;
    const d = (v) => v ? formatThaiDate(v) : '';
    const rows = [
        { heading: 'ข้อมูลส่วนตัว' },
        { label: 'คำนำหน้า', value: w.title },
        { label: 'ชื่อ (อังกฤษ)', value: w.firstName },
        { label: 'นามสกุล (อังกฤษ)', value: w.lastName },
        { label: 'ชื่อไทย (บัตรชมพู)', value: w.thaiName },
        { label: 'เพศ', value: w.gender },
        { label: 'สัญชาติ', value: w.nationality },
        { label: 'วันเกิด', value: d(w.dob) },
        { label: 'ชื่อพ่อ', value: w.fatherName },
        { label: 'ชื่อแม่', value: w.motherName },
        { label: 'อีเมล', value: w.email },
        { heading: 'ใบอนุญาตทำงาน / เลขประจำตัว' },
        { label: 'เลขอ้างอิง', value: w.refNo },
        { label: 'เลขประจำตัวคนต่างด้าว', value: w.workerUid },
        { label: 'เลขที่ใบอนุญาตทำงาน', value: w.permitNo },
        { label: 'ใบอนุญาตหมดอายุ', value: d(w.permitExpiry) },
        { label: 'เลขบัตรชมพู', value: w.pinkCardNo },
        { label: 'ตำแหน่งงาน', value: w.position },
        { label: 'สถานที่ทำงาน', value: w.workplace },
        { heading: 'พาสปอร์ต / CI' },
        { label: 'เลขพาสปอร์ต', value: w.passportNo },
        { label: 'สถานที่ออก', value: w.passportPob },
        { label: 'ผู้ออก', value: w.passportAuth },
        { label: 'วันออก', value: d(w.passportIssue) },
        { label: 'วันหมดอายุ', value: d(w.passportExpiry) },
        { heading: 'อื่น ๆ' },
        { label: 'เลขกรมธรรม์ประกัน', value: w.insuranceNo },
        { label: 'สถานะ', value: WORKER_STATUS_LABELS[w.status] || w.status },
        { label: 'โน้ตถึงเจ้าหน้าที่', value: w.clientNote },
        ...clientWorkerHistoryRows(w),
    ];
    // ตัดช่องว่าง และหัวข้อที่ไม่มีข้อมูลใต้หัวข้อนั้นเลย
    const summary = [];
    let pendingHeading = null;
    rows.forEach(r => {
        if (r.heading) { pendingHeading = r; return; }
        if (r.value == null || String(r.value).trim() === '') return;
        if (pendingHeading) { summary.push(pendingHeading); pendingHeading = null; }
        summary.push(r);
    });
    uiAlert('ดูข้อมูลอย่างเดียว — ถ้าข้อมูลไม่ถูกต้อง กด "เขียนโน้ต" แจ้งเจ้าหน้าที่ได้', {
        title: 'ข้อมูลคนงาน',
        wide: true, // หน้าต่างใหญ่ แบ่งหัวข้อเป็นคอลัมน์ ไม่ต้องเลื่อนลง
        okText: 'ปิด',
        card: { image: w.photo || '', imageIcon: 'user', title: workerFullName(w), subtitle: [w.nationality, w.workerUid].filter(Boolean).join(' • '), rows: [] },
        summary
    });
}

// ประวัติงานและค่าบริการของคนงานคนนี้ (owner 2026-10-19) — เฉพาะสิ่งที่นายจ้างเห็นอยู่แล้วในแท็บใบงาน/บิล:
// ค่าบริการตามบิล (ยังไม่ออกบิล = ไม่แสดงยอด ราคาประมาณเป็นข้อมูลภายใน), ไม่มีต้นทุน/ค่าคอม/ค่าธรรมเนียมรัฐแยก
// ยอดค้างนับต่อใบงาน (ใบงานในบิลที่ยังชำระไม่ครบ) จึงไม่ปนยอดของคนงานอื่นในบิลรวม
function clientWorkerHistoryRows(w) {
    const custId = clientCustomerId();
    const list = jobs.filter(j => j.workerId === w.id && j.customerId === custId)
        .sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')));
    if (!list.length) return [];
    let billed = 0, paid = 0;
    const rows = list.map(j => {
        const inv = getJobInvoice(j);
        let money;
        if (isJobNoCharge(j)) money = 'ไม่เรียกเก็บเงิน';
        else if (inv) {
            const fee = Number(j.fee || 0);
            const isPaid = inv.status === 'paid' || invoiceBalance(inv) <= 0;
            billed += fee;
            if (isPaid) paid += fee;
            money = `${fmtMoney(fee)} บาท • ${inv.invoiceNo} • ${isPaid ? 'ชำระแล้ว' : 'ค้างชำระ'}`;
        } else money = 'ยังไม่ออกบิล';
        const when = formatThaiDate(String(j.createdAt || j.updatedAt || '').slice(0, 10));
        return { label: `${getCleanJobTypeName(j.jobType)} (${getJobDisplayNo(j)})`, value: `${when} • ${j.status || '-'} • ${money}` };
    });
    const totals = billed > 0 ? [
        { label: 'ค่าบริการที่ออกบิลแล้วรวม', value: `${fmtMoney(round2(billed))} บาท` },
        { label: 'ชำระแล้ว', value: `${fmtMoney(round2(paid))} บาท` },
        { label: 'ยังค้างชำระ', value: `${fmtMoney(round2(billed - paid))} บาท` },
    ] : [];
    return [{ heading: 'ประวัติงานและค่าบริการ' }, ...totals, ...rows];
}

// ---------- นายจ้างแจ้งออกคนงานเอง (owner 2026-10-21) — RPC client_request_exit / client_cancel_exit ----------
// เปิดใบงาน "แจ้งออกคนงานต่างด้าว" สถานะรอดำเนินการทันที ไม่มีช่องเหตุผล (owner) — คนงานยังเป็นปกติจนเจ้าหน้าที่ปิดงาน
function clientOpenExitJob(w) {
    return jobs.find(j => j.workerId === w.id && isJobStatusOpen(j.status) && getCleanJobTypeName(j.jobType) === EXIT_JOB_TYPE) || null;
}

// ยกเลิกเองได้เฉพาะคำขอที่ลูกค้าเปิดเอง ยังรอดำเนินการ และยังไม่ออกบิล (ฐานข้อมูลตรวจซ้ำ)
function clientExitCancellable(j) {
    return !!j && j.openedByClient && j.status === 'รอดำเนินการ' && !getJobInvoice(j) && !isJobNoCharge(j);
}

function clientExitButtonHtml(w) {
    if (w.status === 'archived' || w.status === 'deleted') return '';
    const j = clientOpenExitJob(w);
    if (!j) return `<button type="button" class="btn btn-sm btn-outline cp-exit-btn" onclick="clientRequestExit('${w.id}')" title="แจ้งออกคนงาน">${icon('outbox')} แจ้งออก</button>`;
    return clientExitCancellable(j)
        ? `<button type="button" class="btn btn-sm btn-outline" onclick="clientCancelExit('${j.id}')" title="ยกเลิกคำขอแจ้งออก">${icon('bad')} ยกเลิกแจ้งออก</button>` : '';
}

async function clientRequestExit(workerId) {
    const w = workers.find(x => x.id === workerId);
    if (!w) return;
    const d = (v) => v ? formatThaiDate(v) : '';
    const ok = await uiConfirm('ตรวจสอบข้อมูลคนงานที่จะแจ้งออก — เจ้าหน้าที่จะได้รับแจ้งทันทีและดำเนินการแจ้งออกกับกรมการจัดหางานให้', {
        title: 'แจ้งออกคนงาน', okText: 'ยืนยันแจ้งออก', danger: true,
        card: {
            image: w.photo || '', imageIcon: 'user', title: workerFullName(w),
            subtitle: [w.nationality, w.gender ? `เพศ: ${w.gender}` : ''].filter(Boolean).join(' • '),
            rows: [
                ['ชื่อไทย (บัตรชมพู)', w.thaiName],
                ['เลขประจำตัวคนต่างด้าว', w.workerUid],
                ['เลขที่ใบอนุญาตทำงาน', w.permitNo],
                ['ใบอนุญาตหมดอายุ', d(w.permitExpiry)],
                ['เลขพาสปอร์ต', w.passportNo],
                ['วันเกิด', d(w.dob)],
                ['ตำแหน่งงาน', w.position],
            ],
        }
    });
    if (!ok) return;
    const res = await callCloudAPI("clientRequestExit", { workerId: w.id });
    if (!res || res.status !== "success") { showToast("❌ แจ้งออกไม่สำเร็จ: " + (res && res.message ? res.message : "กรุณาลองใหม่"), "danger"); return; }
    await loadData(); // ดึงใบงานที่ฐานข้อมูลสร้างให้
    showUploadPill('ok', `แจ้งออก ${workerFullName(w)} แล้ว`, 'ดูความคืบหน้าได้ที่แท็บ "งานที่แจ้ง"');
    renderClientPortal();
}

async function clientCancelExit(jobId) {
    const j = jobs.find(x => x.id === jobId);
    const w = j && workers.find(x => x.id === j.workerId);
    if (!j || !(await uiConfirm('ยกเลิกคำขอแจ้งออกคนงานคนนี้?', { title: 'ยกเลิกแจ้งออก', okText: 'ยกเลิกคำขอ', danger: true, card: dialogCardForWorker(w) }))) return;
    const res = await callCloudAPI("clientCancelExit", { jobId });
    if (!res || res.status !== "success") { showToast("❌ ยกเลิกไม่สำเร็จ: " + (res && res.message ? res.message : "กรุณาลองใหม่"), "danger"); return; }
    await loadData();
    showUploadPill('ok', 'ยกเลิกคำขอแจ้งออกแล้ว', w ? workerFullName(w) : '');
    renderClientPortal();
}

// แท็บ "คนงานของฉัน" — ตารางแบบเดียวกับหน้าข้อมูลคนงานต่างด้าว (รูป, เลขคนงาน/บัตร, พาสปอร์ต, วันหมดอายุ, สถานะเอกสาร)
// แบ่งกลุ่มตามวันที่ใบอนุญาตทำงานหมดอายุ (ใกล้หมดก่อน) — ไม่มีวันหมดอายุ / แจ้งออกแล้ว อยู่กลุ่มท้าย
function renderClientWorkersTab(list) {
    const q = (document.getElementById("cp-worker-search") || {}).value || '';
    const query = q.trim().toLowerCase();
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const daysTo = (d) => d ? Math.ceil((d - today) / 86400000) : null;
    const nats = [...new Set(list.map(w => w.nationality).filter(Boolean))].sort();
    if (cpFilters.workerNat && !nats.includes(cpFilters.workerNat)) cpFilters.workerNat = '';
    const shown = list.filter(w => !query || [w.firstName, w.lastName, w.thaiName, w.refNo, w.workerUid, w.passportNo, w.permitNo, w.pinkCardNo, w.nationality]
        .filter(Boolean).join(' ').toLowerCase().includes(query))
        .filter(w => !cpFilters.workerStatus || (cpFilters.workerStatus === 'notify' ? workerNeedsNotifyEntry(w) : clientWorkerDocState(w) === cpFilters.workerStatus))
        .filter(w => !cpFilters.workerNat || w.nationality === cpFilters.workerNat);

    // จัดกลุ่ม: วันหมดอายุใบอนุญาต (yyyy-mm-dd) → คนงาน
    const groups = {};
    shown.forEach(w => {
        const exp = safeParseDate(w.permitExpiry);
        const key = w.status === 'archived' ? 'z-archived' : exp ? localDateISO(exp) : 'y-none';
        (groups[key] = groups[key] || { key, date: exp, list: [] }).list.push(w);
    });
    const ordered = Object.values(groups).sort((a, b) => a.key.localeCompare(b.key));

    const statusBadgeOf = (w) => {
        const s = CP_WORKER_STATES[clientWorkerDocState(w)];
        // ยังแจ้งเข้าไม่เสร็จ → ป้ายเพิ่มใต้สถานะเอกสาร (ลูกค้าเห็นว่าคนนี้ยังรอเจ้าหน้าที่แจ้งเข้า, owner 2026-10-14)
        const notify = workerNeedsNotifyEntry(w)
            ? `<div class="cp-notify-badge"><span class="badge badge-warning" title="เจ้าหน้าที่ยังแจ้งเข้าคนงานคนนี้กับกรมการจัดหางานไม่เสร็จ">${icon('hourglass')} รอแจ้งเข้า</span></div>` : '';
        const exitJob = clientOpenExitJob(w);
        const exit = exitJob
            ? `<div class="cp-notify-badge"><span class="badge badge-danger" title="แจ้งออกเมื่อ ${formatThaiDate(String(exitJob.createdAt || '').slice(0, 10))} • ${escapeHtml(exitJob.status)}">${icon('hourglass')} แจ้งออกแล้ว รอเจ้าหน้าที่</span></div>` : '';
        return `<span class="badge badge-lg ${s.cls}">${s.label}</span>${notify}${exit}`;
    };

    const row = (w) => {
        const pExp = safeParseDate(w.passportExpiry), wpExp = safeParseDate(w.permitExpiry);
        return `
            <tr class="clickable-row ${w.status === 'archived' ? 'is-voided-row' : ''}" ondblclick="handleRowDblClick(event) && openClientWorkerView('${w.id}')" title="ดับเบิลคลิกเพื่อดูข้อมูลคนงาน">
                <td>
                    <div><strong>${escapeHtml(w.refNo || '-')}</strong></div>
                    <div class="worker-id-line"><span>เลขประจำตัวคนต่างด้าว</span> <b>${escapeHtml(w.workerUid || '-')}</b></div>
                    <div class="worker-id-line"><span>เลขที่ใบอนุญาตทำงาน</span> <b>${escapeHtml(w.permitNo || '-')}</b></div>
                </td>
                <td>
                    <div class="renewal-worker-cell">
                        <div class="renewal-avatar"><img src="${w.photo ? escapeHtml(w.photo) : WORKER_AVATAR_PLACEHOLDER}" alt="" loading="lazy"></div>
                        <div>
                            <strong>${escapeHtml(workerFullName(w))}</strong>
                            ${w.thaiName ? `<div><small class="text-muted">ชื่อไทย (บัตรชมพู): ${escapeHtml(w.thaiName)}</small></div>` : ''}
                            <div><small class="text-muted">เพศ: ${escapeHtml(w.gender || '-')}</small></div>
                        </div>
                    </div>
                </td>
                <td><span class="badge badge-gold">${escapeHtml(w.nationality || '-')}</span></td>
                <td><div>เล่ม: ${escapeHtml(w.passportNo || '-')}</div></td>
                <td class="worker-expiry-cell">
                    ${renderWorkerExpiryLine('ใบอนุญาต', wpExp, daysTo(wpExp), 60)}
                    ${renderWorkerExpiryLine('พาสปอร์ต', pExp, daysTo(pExp), 180)}
                </td>
                <td>${statusBadgeOf(w)}</td>
                <td class="cp-note-cell">${w.clientNote ? `<span class="cp-note-text" title="${escapeHtml(w.clientNote)}">${escapeHtml(w.clientNote)}</span>` : '<span class="text-muted">-</span>'}</td>
                <td class="actions-col">
                    <div class="cp-worker-actions">
                        <button type="button" class="btn btn-sm btn-gold btn-open-folder" onclick="openWorkerFolderModal('${w.id}')">${icon('folder')} เปิดแฟ้มเอกสาร</button>
                        <button type="button" class="btn btn-sm btn-outline" onclick="openClientWorkerNote('${w.id}')">${icon('edit')} ${w.clientNote ? 'แก้โน้ต' : 'เขียนโน้ต'}</button>
                        ${clientExitButtonHtml(w)}
                    </div>
                </td>
            </tr>`;
    };

    const groupTitle = (g) => g.key === 'z-archived' ? 'พ้นสภาพ / แจ้งออกแล้ว'
        : g.key === 'y-none' ? 'ยังไม่มีวันหมดอายุใบอนุญาต'
        : `ใบอนุญาตหมดอายุ ${formatThaiDate(g.date)}`;
    const groupHint = (g) => {
        if (!g.date || g.key === 'z-archived') return '';
        const d = daysTo(g.date);
        // ไม่นับจำนวนวันที่เหลือ/เกินมา — บอกแค่สถานะ (owner, 2026-10-14)
        return d < 0 ? `<span class="text-danger">หมดอายุแล้ว</span>` : d <= 60 ? `<span class="text-warning">ใกล้หมดอายุ</span>` : '';
    };

    const panels = ordered.map(g => `
        <div class="dashboard-panel cp-worker-group">
            <div class="panel-header">
                <h3>${icon('calendar')} ${groupTitle(g)}</h3>
                <span class="cp-worker-group-meta">${g.list.length} คน ${groupHint(g)}</span>
            </div>
            <div class="panel-content" style="padding: 0; overflow-x: auto;">
                <table class="data-table cp-workers-table" style="box-shadow: none; border: none; border-radius: 0;">
                    <colgroup><col class="cw-id"><col class="cw-name"><col class="cw-nat"><col class="cw-pp"><col class="cw-exp"><col class="cw-status"><col class="cw-note"><col class="cw-act"></colgroup>
                    <thead><tr><th>เลขคนงาน / บัตร</th><th>ชื่อ-นามสกุล</th><th>สัญชาติ</th><th>ข้อมูลพาสปอร์ต</th><th>วันหมดอายุ</th><th>สถานะเอกสาร</th><th>โน้ตถึงเจ้าหน้าที่</th><th class="actions-col">เอกสาร / โน้ต</th></tr></thead>
                    <tbody>${[...g.list].sort((a, b) => `${a.firstName}`.localeCompare(`${b.firstName}`)).map(row).join('')}</tbody>
                </table>
            </div>
        </div>`).join('');

    return `
        <div class="cp-card">
            <div class="cp-toolbar"><div class="search-box"><input type="text" id="cp-worker-search" placeholder="ค้นหาชื่อ-นามสกุล, เลขคนงาน, พาสปอร์ต..." value="${escapeHtml(q)}" oninput="renderClientPortalKeepFocus('cp-worker-search')"></div>
                <select class="select-filter" onchange="setClientPortalFilter('workerStatus', this.value)" title="กรองตามสถานะเอกสาร">
                    <option value="">ทุกสถานะ</option>${Object.entries(CP_WORKER_STATES).map(([k, s]) => `<option value="${k}" ${cpFilters.workerStatus === k ? 'selected' : ''}>${s.label} (${list.filter(w => clientWorkerDocState(w) === k).length})</option>`).join('')}
                    <option value="notify" ${cpFilters.workerStatus === 'notify' ? 'selected' : ''}>รอแจ้งเข้า (${list.filter(workerNeedsNotifyEntry).length})</option>
                </select>
                ${nats.length > 1 ? `<select class="select-filter" onchange="setClientPortalFilter('workerNat', this.value)" title="กรองตามสัญชาติ">
                    <option value="">ทุกสัญชาติ</option>${nats.map(n => `<option value="${escapeHtml(n)}" ${cpFilters.workerNat === n ? 'selected' : ''}>${escapeHtml(n)}</option>`).join('')}
                </select>` : ''}
                ${ordered.length > 1 ? cpCollapseButtons() : ''}
                <span class="text-muted">${shown.length} คน • แบ่งกลุ่มตามวันที่ใบอนุญาตทำงานหมดอายุ • กดหัวกลุ่มเพื่อยุบ/กาง • กด "เปิดแฟ้มเอกสาร" เพื่อดู/ดาวน์โหลดเอกสาร</span></div>
            ${panels || '<p class="text-muted" style="text-align:center; padding:24px;">ไม่พบคนงาน</p>'}
        </div>`;
}

// พอร์ทัลนายจ้าง: เอกสารปิดงานดาวน์โหลดได้เมื่อบิลของงานนั้นชำระครบแล้ว หรืองานตั้งเป็น "ไม่เรียกเก็บเงิน"
// ยังไม่ออกบิล / บิลค้างหรือจ่ายบางส่วน → ซ่อนลิงก์ (เจ้าของระบบกำหนด 2026-10-09) — แฟ้มเอกสารคนงานยังเปิดได้ตามเดิม
// Admin เปิดล็อกรายลูกค้าได้ที่หน้าจัดการผู้ใช้ (customers.unlockUnpaidJobDocs, toggleCustomerDocsLock)
function clientJobDocsUnlocked(j) {
    if (isJobNoCharge(j)) return true;
    if ((customers.find(c => c.id === j.customerId) || {}).unlockUnpaidJobDocs) return true;
    const inv = getJobInvoice(j);
    return !!inv && invoiceBalance(inv) <= 0;
}

function renderClientJobsTab(list) {
    const monthSel = document.getElementById("cp-job-month");
    const month = monthSel ? monthSel.value : localDateISO(new Date()).slice(0, 7);
    const months = [...new Set(list.map(jobMonthKey).filter(k => /^\d{4}-\d{2}$/.test(k)))];
    const thisMonth = localDateISO(new Date()).slice(0, 7);
    if (!months.includes(thisMonth)) months.push(thisMonth);
    months.sort().reverse();
    const inMonth = list.filter(j => !month || jobMonthKey(j) === month);
    const types = [...new Set(inMonth.map(j => getCleanJobTypeName(j.jobType)).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'th'));
    if (cpFilters.jobType && !types.includes(cpFilters.jobType)) cpFilters.jobType = '';
    const shown = inMonth
        .filter(j => !cpFilters.jobStatus || j.status === cpFilters.jobStatus)
        .filter(j => !cpFilters.jobType || getCleanJobTypeName(j.jobType) === cpFilters.jobType)
        .sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')));
    const statusCls = { 'รอดำเนินการ': 'badge-warning', 'กำลังดำเนินการ': 'badge-gold', 'รอเอกสารเพิ่มเติม': 'badge-danger', 'ปิดงานแล้ว': 'badge-success' };
    const STATUS_ORDER = ['รอเอกสารเพิ่มเติม', 'รอดำเนินการ', 'กำลังดำเนินการ', 'ปิดงานแล้ว'];

    const row = (j) => {
        const w = workers.find(x => x.id === j.workerId);
        const docs = Array.isArray(j.attachments) ? j.attachments : [];
        return `<tr>
            <td><strong>${getJobDisplayNo(j)}</strong></td>
            <td>${escapeHtml(getCleanJobTypeName(j.jobType))}</td>
            <td>${escapeHtml(w ? workerFullName(w) : '-')}</td>
            <td>${formatThaiDate(String(j.createdAt || j.updatedAt || '').slice(0, 10))}</td>
            <td><span class="badge ${statusCls[j.status] || ''}">${escapeHtml(j.status || '-')}</span>${j.status === 'ปิดงานแล้ว' && j.closedAt ? `<br><small class="text-muted">ปิดเมื่อ ${formatThaiDate(j.closedAt)}</small>` : ''}${j.appointmentDate && isJobStatusOpen(j.status) ? `<br><small class="text-muted">นัด ${formatThaiDate(j.appointmentDate)}${j.appointmentTime ? ` ${escapeHtml(j.appointmentTime)}` : ''}</small>` : ''}${getCleanJobTypeName(j.jobType) === EXIT_JOB_TYPE && clientExitCancellable(j) ? `<div><button type="button" class="btn btn-sm btn-outline" style="margin-top:6px;" onclick="clientCancelExit('${j.id}')" title="ยกเลิกคำขอแจ้งออก">${icon('bad')} ยกเลิกแจ้งออก</button></div>` : ''}</td>
            <td>${docs.length && !clientJobDocsUnlocked(j) ? `<span class="text-muted" title="เอกสาร ${docs.length} ไฟล์">${icon('lock')} ชำระเงินเพื่อดาวน์โหลดเอกสาร</span>` : docs.length ? `<button type="button" class="btn btn-sm btn-outline" onclick="shareJobCloseFolder('${j.id}', true)" title="เปิดโฟลเดอร์เอกสารปิดงาน (ดู/ดาวน์โหลดทั้งหมด)">${icon('folder')} เปิดโฟลเดอร์ (${docs.length} ไฟล์)</button>` : '<span class="text-muted">-</span>'}</td>
        </tr>`;
    };

    // แบ่งกลุ่มตามสถานะงาน — กดหัวกลุ่มเพื่อยุบ/กาง (จำไว้ต่อเครื่อง)
    const groups = {};
    shown.forEach(j => { const s = j.status || 'อื่น ๆ'; (groups[s] = groups[s] || []).push(j); });
    const ordered = Object.keys(groups).sort((a, b) => {
        const ia = STATUS_ORDER.indexOf(a), ib = STATUS_ORDER.indexOf(b);
        return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib);
    });
    const panels = ordered.map(s => `
        <div class="dashboard-panel cp-worker-group">
            <div class="panel-header">
                <h3>${icon('clipboard')} งาน${escapeHtml(s)}</h3>
                <span class="cp-worker-group-meta">${groups[s].length} งาน</span>
            </div>
            <div class="panel-content" style="padding: 0; overflow-x: auto;">
                <table class="data-table cp-jobs-table" style="box-shadow: none; border: none; border-radius: 0;">
                    <colgroup><col class="cj-no"><col class="cj-type"><col class="cj-worker"><col class="cj-date"><col class="cj-status"><col class="cj-docs"></colgroup>
                    <thead><tr><th>เลขที่แจ้งงาน</th><th>ประเภทงาน</th><th>คนงาน</th><th>วันที่แจ้ง</th><th>สถานะ</th><th>เอกสารปิดงาน</th></tr></thead>
                    <tbody>${groups[s].map(row).join('')}</tbody>
                </table>
            </div>
        </div>`).join('');

    return `
        <div class="cp-card">
            <div class="cp-toolbar">
                <select id="cp-job-month" class="select-filter" onchange="renderClientPortal()" title="กรองตามเดือนที่แจ้งงาน">
                    <option value="">ทุกเดือน</option>${months.map(k => `<option value="${k}" ${k === month ? 'selected' : ''}>${monthLabelTh(k)}</option>`).join('')}
                </select>
                <select class="select-filter" onchange="setClientPortalFilter('jobStatus', this.value)" title="กรองตามสถานะงาน">
                    <option value="">ทุกสถานะ</option>${STATUS_ORDER.map(s => `<option value="${s}" ${cpFilters.jobStatus === s ? 'selected' : ''}>${s} (${inMonth.filter(j => j.status === s).length})</option>`).join('')}
                </select>
                ${types.length > 1 ? `<select class="select-filter" onchange="setClientPortalFilter('jobType', this.value)" title="กรองตามประเภทงาน">
                    <option value="">ทุกประเภทงาน</option>${types.map(t => `<option value="${escapeHtml(t)}" ${cpFilters.jobType === t ? 'selected' : ''}>${escapeHtml(t)}</option>`).join('')}
                </select>` : ''}
                ${ordered.length > 1 ? cpCollapseButtons() : ''}
                <span class="text-muted">${shown.length} งาน • ปิดแล้ว ${shown.filter(j => j.status === 'ปิดงานแล้ว').length} • ยังไม่ปิด ${shown.filter(j => isJobStatusOpen(j.status)).length}</span>
            </div>
            ${panels || `<p class="text-muted" style="text-align:center; padding:24px;">ไม่มีงานที่ตรงกับตัวกรอง</p>`}
        </div>`;
}

function renderClientBalanceTab(myInvoices, custId) {
    const open = myInvoices.filter(i => (i.status === 'issued' || i.status === 'partial') && invoiceBalance(i) > 0)
        .sort((a, b) => (a.issueDate || '').localeCompare(b.issueDate || ''));
    const total = round2(open.reduce((s, i) => s + invoiceBalance(i), 0));
    const credit = customerCredit(custId);
    const bank = banks[0];
    return `
        <div class="cp-card">
            <div class="pay-summary">
                <div class="${total > 0 ? 'is-due' : 'is-done'}"><span>ยอดค้างชำระรวม</span><strong>${fmtMoney(total)}</strong></div>
                <div><span>จำนวนบิลค้าง</span><strong>${open.length}</strong></div>
                <div class="is-paid"><span>มัดจำ/เงินรับล่วงหน้าคงเหลือ</span><strong>${fmtMoney(credit)}</strong></div>
            </div>
            <div class="table-container"><table class="data-table">
                <thead><tr><th>เลขที่บิล</th><th>วันที่ออกบิล</th><th>กำหนดชำระ</th><th class="inv-num">ยอดบิล</th><th class="inv-num">ชำระแล้ว</th><th class="inv-num">คงค้าง</th><th></th></tr></thead>
                <tbody>${open.length ? open.map(i => `
                    <tr>
                        <td><strong>${escapeHtml(i.invoiceNo)}</strong></td>
                        <td>${formatThaiDate(i.issueDate)}</td>
                        <td>${escapeHtml(i.dueDateText || '-')}</td>
                        <td class="inv-num">${fmtMoney(i.grandTotal)}</td>
                        <td class="inv-num">${fmtMoney(invoicePaidAmount(i))}</td>
                        <td class="inv-num"><strong class="text-danger">${fmtMoney(invoiceBalance(i))}</strong></td>
                        <td class="actions-col"><button type="button" class="btn btn-sm btn-outline" onclick="openStoredInvoice('${i.id}')">${icon('receipt')} ดูบิล</button></td>
                    </tr>`).join('') : `<tr><td colspan="7" class="text-muted" style="text-align:center; padding:24px;">${icon('ok')} ไม่มียอดค้างชำระ</td></tr>`}</tbody>
            </table></div>
            ${total > 0 ? `<p class="text-muted cp-pay-hint">ชำระได้ตามบัญชีที่ระบุในบิลแต่ละใบ แล้วส่งสลิปให้เจ้าหน้าที่ — ระบบจะออกใบเสร็จให้ในแท็บ "ใบเสร็จรับเงิน"</p>` : ''}
        </div>`;
}

function renderClientReceiptsTab(myInvoices, custId) {
    const invIds = new Set(myInvoices.map(i => i.id));
    // ใบเสร็จแบบใหม่ (receipts) + การรับเงินแบบเก่าที่ไม่มีใบเสร็จแยก
    const rows = [
        ...receipts.filter(r => r.customerId === custId && !r.voided).map(r => ({
            no: r.receiptNo, date: r.paidDate, amount: r.amount, method: r.method === 'cash' ? 'เงินสด' : paymentMethodLabel(r),
            ref: [...new Set(liveAllocationsOf(r.id).map(p => (invoices.find(i => i.id === p.invoiceId) || {}).invoiceNo).filter(Boolean))].join(', ') || 'มัดจำ',
            open: `openReceiptDoc('${r.id}')`
        })),
        ...payments.filter(p => !p.voided && !p.receiptId && invIds.has(p.invoiceId)).map(p => ({
            no: p.receiptNo, date: p.paidDate, amount: p.amount, method: paymentMethodLabel(p),
            ref: (invoices.find(i => i.id === p.invoiceId) || {}).invoiceNo || '-', open: `openReceiptModal('${p.id}')`
        }))
    ].sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')));
    const total = round2(rows.reduce((s, r) => s + (Number(r.amount) || 0), 0));
    return `
        <div class="cp-card">
            <div class="cp-toolbar"><span class="text-muted">ใบเสร็จที่ฝ่ายบัญชีออกให้แล้ว ${rows.length} ใบ • รวม ${fmtMoney(total)} บาท — กด "ดู/พิมพ์" เพื่อเปิดใบเสร็จ</span></div>
            <div class="table-container"><table class="data-table">
                <thead><tr><th>เลขที่ใบเสร็จ</th><th>วันที่รับเงิน</th><th>อ้างอิงบิล</th><th>ช่องทาง</th><th class="inv-num">จำนวนเงิน</th><th></th></tr></thead>
                <tbody>${rows.length ? rows.map(r => `
                    <tr>
                        <td><strong>${escapeHtml(r.no || '-')}</strong></td>
                        <td>${formatThaiDate(r.date)}</td>
                        <td>${escapeHtml(r.ref)}</td>
                        <td>${escapeHtml(r.method)}</td>
                        <td class="inv-num"><strong>${fmtMoney(r.amount)}</strong></td>
                        <td class="actions-col"><button type="button" class="btn btn-sm btn-outline" onclick="${r.open}">${icon('print')} ดู/พิมพ์</button></td>
                    </tr>`).join('') : `<tr><td colspan="6" class="text-muted" style="text-align:center; padding:24px;">ยังไม่มีใบเสร็จ</td></tr>`}</tbody>
            </table></div>
        </div>`;
}

// พิมพ์ค้นหาแล้ววาดแท็บใหม่ — คงเคอร์เซอร์ไว้ในช่องค้นหา
function renderClientPortalKeepFocus(inputId) {
    const el = document.getElementById(inputId);
    const pos = el ? el.selectionStart : null;
    renderClientPortal();
    const again = document.getElementById(inputId);
    if (again) { again.focus(); if (pos !== null) again.setSelectionRange(pos, pos); }
}

function readSessionValue(key) {
    try { return sessionStorage.getItem(key); } catch (e) { return null; }
}
function writeSessionValue(key, value) {
    try { sessionStorage.setItem(key, value); } catch (e) { /* ไม่มี storage ก็แค่จำหน้าไม่ได้ */ }
}

function switchView(viewName) {
    writeSessionValue('mw_last_view', viewName);
    closeWorkerQuickView(); // แผงข้อมูลคนงานผูกกับตารางหน้าเดิม — เปลี่ยนหน้าแล้วปิด
    // ออกจากหน้าที่กำลังกรองจากกระดิ่ง → ล้างตัวกรองนั้น (กลับมาหน้าเดิมทีหลังเห็นรายการครบตามปกติ)
    if (bellFilter && viewName !== (bellFilter.view === 'billing' ? 'expenses' : bellFilter.view)) bellFilter = null;
    // Toggles sections
    const sections = document.querySelectorAll(".content-section");
    sections.forEach(sec => sec.classList.add("hidden"));
    
    const activeSection = document.getElementById(`view-${viewName}`);
    if (activeSection) {
        activeSection.classList.remove("hidden");
    }

    // Toggle Sidebar active menu item
    const menuItems = document.querySelectorAll(".menu-item");
    menuItems.forEach(item => item.classList.remove("active"));
    
    const activeMenu = document.getElementById(`menu-${viewName}`);
    if (activeMenu) {
        activeMenu.classList.add("active");
    }

    // Update Topbar Title
    const titleEl = document.getElementById("topbar-title");
    if (viewName === 'dashboard') titleEl.innerText = "แดชบอร์ดระบบและการแจ้งเตือน";
    if (viewName === 'customers') titleEl.innerText = "ฐานข้อมูลนายจ้าง / ลูกค้าผู้ว่าจ้าง";
    if (viewName === 'workers') titleEl.innerText = "ฐานข้อมูลคนงานต่างด้าว";
    if (viewName === 'jobs') titleEl.innerText = "ระบบจัดการแจ้งงาน";
    if (viewName === 'renewals') titleEl.innerText = "ข้อมูลคนงานต่ออายุ/ทำเล่ม (จัดกลุ่มตามวันหมดอายุใบอนุญาต)";
    if (viewName === 'agents') titleEl.innerText = "จัดการ Agent (ผู้ส่งงาน / ผู้แนะนำลูกค้า)";
    if (viewName === 'expenses') titleEl.innerText = "การเงิน, รายจ่าย และบัญชีธนาคาร";
    if (viewName === 'users') titleEl.innerText = "จัดการบัญชีผู้ใช้งานระบบ";
    if (viewName === 'calendar') titleEl.innerText = "ปฏิทินทีม";
    const calBtn = document.getElementById('topbar-calendar-btn');
    if (calBtn) calBtn.classList.toggle('is-active', viewName === 'calendar');
    if (viewName === 'client-portal') titleEl.innerText = "ข้อมูลของบริษัทฉัน";
    if (viewName === 'backup') {
        titleEl.innerText = "สำรองและกู้คืนข้อมูลระบบ";
        renderLastBackupInfo();
        renderDriveBackupStatus();
        openLargeFilesTool();
    }

    // Refresh contents
    if (viewName === 'dashboard') {
        renderDashboard();
    } else if (viewName === 'customers') {
        renderCustomers();
    } else if (viewName === 'workers') {
        renderWorkers();
        updateEmployerDropdownOptions();
    } else if (viewName === 'jobs') {
        renderJobs();
    } else if (viewName === 'renewals') {
        renderRenewalGroups();
        loadRenewals(true); // เพื่อนร่วมทีมอาจเริ่ม/ทำขั้นต่ออายุไปแล้ว
    } else if (viewName === 'agents') {
        renderAgentsList();
    } else if (viewName === 'expenses') {
        // กลับไปแท็บย่อยที่เปิดค้างไว้ล่าสุด (ปุ่มรีเฟรช / F5 / กดเมนูซ้ำ ไม่เด้งกลับไปสรุปการเงิน)
        const lastFinTab = readSessionValue('mw_last_fin_tab');
        const finBtn = lastFinTab ? document.getElementById(`btn-finpage-tab-${lastFinTab}`) : null;
        switchFinancePageTab(finBtn && getComputedStyle(finBtn).display !== 'none' ? lastFinTab : 'overview');
    } else if (viewName === 'client-portal') {
        renderClientPortal();
    } else if (viewName === 'users') {
        renderUsers();
    } else if (viewName === 'calendar') {
        openCalendarView();
    }
    // ตัวเลขบนกระดิ่งต้องตรงกับผู้ใช้/ข้อมูลปัจจุบันทุกหน้า (เดิมอัปเดตแค่ตอนวาดแดชบอร์ด — บัญชี client ไม่เคยเข้าแดชบอร์ด เลยเห็นเลขค้างของบัญชีก่อนหน้า)
    if (viewName !== 'dashboard') updateNotificationBell();

    // บนจอมือถือ/แท็บเล็ต เมนูข้างเป็นลิ้นชักเลื่อนออกมา — เลือกเมนูแล้วปิดลิ้นชักให้อัตโนมัติ
    closeMobileSidebar();
    setTimeout(backgroundRefresh, 0); // วาดหน้าด้วยข้อมูลที่มีก่อน แล้วค่อยดึงใหม่เบื้องหลังถ้าเก่ากว่า 1 นาที
}

// ==================== เมนูข้างแบบลิ้นชักบนจอมือถือ/แท็บเล็ต (Responsive Sidebar Drawer) ====================
// จอกว้าง (คอมพิวเตอร์/iPad แนวนอน) เมนูข้างจะแสดงค้างอยู่ตลอดตามปกติ (ดู styles.css)
// จอแคบ (มือถือ/iPad แนวตั้ง, <=1024px) เมนูข้างจะซ่อนไว้แล้วเลื่อนออกมาเมื่อกดปุ่มแฮมเบอร์เกอร์
function toggleMobileSidebar() {
    document.querySelector(".sidebar")?.classList.toggle("sidebar-open");
    document.getElementById("sidebar-overlay")?.classList.toggle("visible");
}

function closeMobileSidebar() {
    document.querySelector(".sidebar")?.classList.remove("sidebar-open");
    document.getElementById("sidebar-overlay")?.classList.remove("visible");
}

